// ══════════════════════════════════════════════════════════════════════════════
// SEÇÃO 1: CONFIGURAÇÕES - EDITE AQUI
// ══════════════════════════════════════════════════════════════════════════════

const CONFIG = {
  // ┌────────────────────────────────────────────────────────────────────────────┐
