  // ┌────────────────────────────────────────────────────────────────────────────┐
  // │ 🧪 MODO DE TESTE - Processa apenas alguns vídeos para validar             │
  // └────────────────────────────────────────────────────────────────────────────┘
  modoTeste: {
    ativo: false,
    maxVideos: 5,
  },

  // ┌────────────────────────────────────────────────────────────────────────────┐
  // │ 🔍 MODO DRY-RUN - Simula sem executar                                     │
  // └────────────────────────────────────────────────────────────────────────────┘
  dryRun: {
    ativo: false,
    mostrarComandos: true,
    simularTempo: true
  },

  // ┌────────────────────────────────────────────────────────────────────────────┐
  // │ 🐛 DEBUG MODE - Logs detalhados (v2.6)                                    │
  // └────────────────────────────────────────────────────────────────────────────┘
  debug: {
    habilitado: false,
    mostrarComandoFFmpeg: true,
    mostrarProgressoGrupo: true,
    salvarLogErro: true,
    arquivoLogErro: 'ffmpeg_erro.log',
    diagnosticarVideos: false  // Analisa resolução/fps/codec (adiciona ~5s)
  },

  // ┌────────────────────────────────────────────────────────────────────────────┐
  // │ PASTAS RAIZ onde procurar obras                                           │
  // └────────────────────────────────────────────────────────────────────────────┘
  pastasRaiz: [
