  // ┌────────────────────────────────────────────────────────────────────────────┐
  // │ PADRÃO DE NOME DOS VÍDEOS                                                 │
  // └────────────────────────────────────────────────────────────────────────────┘
  padraoVideo: /video_pag_(\d+)_sem_trilha\.mp4$/i,
  sufixoObrigatorio: '_sem_trilha',
  sufixosIgnorar: ['_temp', '_preview', '_shorts', '_backup', '_old'],

  // ┌────────────────────────────────────────────────────────────────────────────┐
