  // └────────────────────────────────────────────────────────────────────────────┘
  encoding: {
    crf: 40,
    crfMinimo: 28,
    crfMaximo: 45,
    preset: 'ultrafast',
    videoCodec: 'libx264',
    audioCodec: 'aac',
    audioBitrate: '128k',
    audioSampleRate: 24000,   // ⚠️ CRÍTICO: Manter 24000Hz
    audioChannels: 1,         // ⚠️ CRÍTICO: Manter mono
    pixFmt: 'yuv420p'
  },

  // ┌────────────────────────────────────────────────────────────────────────────┐
  // │ UPSCALE - Aplicado NO FINAL (mais rápido que durante merge)               │
  // └────────────────────────────────────────────────────────────────────────────┘
  upscale: {
    habilitado: true,
    largura: 1920,
    altura: 1080,
    algoritmo: 'lanczos',
    apenasSeNecessario: true,
    tolerancia: 50
