  // │ 🆕 WEBHOOK - Notificações HTTP (v2.6)                                     │
  // └────────────────────────────────────────────────────────────────────────────┘
  webhook: {
    habilitado: false,
    url: 'https://seu-webhook.com/notificacao',
    timeout: 5000,
    eventos: {
      inicio: true,
      conclusao: true,
      erro: true,
