  // ┌────────────────────────────────────────────────────────────────────────────┐
  // │ 🆕 DASHBOARD - Dados para monitoramento externo (v2.6)                    │
  // └────────────────────────────────────────────────────────────────────────────┘
  dashboard: {
    habilitado: true,
    arquivoData: 'merge_dashboard.json',
    atualizarDuranteMerge: true
  },

  // ┌────────────────────────────────────────────────────────────────────────────┐
  // │ 🆕 PADRÕES DE FALHA - Registro de erros (v2.6)                            │
  // └────────────────────────────────────────────────────────────────────────────┘
  padroesFalha: {
    habilitado: true,
    arquivoLog: '.merge_falhas.json',
    maxRegistros: 100
  },

  // ┌────────────────────────────────────────────────────────────────────────────┐
  // │ 🆕 MONITORAMENTO DE SISTEMA (v2.6) - Desabilitado por padrão              │
  // └────────────────────────────────────────────────────────────────────────────┘
  monitoramento: {
    habilitado: false,    // ⚠️ DESABILITADO: Adiciona ~5-10s overhead
    intervaloMs: 5000,
    salvarLog: true,
    arquivoLog: 'system_stats.json',
    alertaRAM: 90,
    alertaCPU: 95,
    mostrarResumo: true
  }
};

