/**
 * FileValidator - Validação robusta de arquivos
 */
class FileValidator {
  static exists(caminho) {
    try {
      return fs.existsSync(caminho);
    } catch {
      return false;
    }
  }

  static isValid(caminho) {
    try {
      if (!fs.existsSync(caminho)) return false;
      const stats = fs.statSync(caminho);
      return stats.size > 0;
    } catch {
      return false;
    }
  }

  static hasMinSize(caminho, minBytes = 1024) {
    try {
      if (!fs.existsSync(caminho)) return false;
      const stats = fs.statSync(caminho);
      return stats.size >= minBytes;
    } catch {
      return false;
    }
  }

  static getSize(caminho) {
    try {
      if (!fs.existsSync(caminho)) return 0;
      return fs.statSync(caminho).size;
    } catch {
      return 0;
    }
  }

  static getSizeFormatted(caminho) {
    const bytes = FileValidator.getSize(caminho);
    if (bytes === 0) return '0 B';

    const units = ['B', 'KB', 'MB', 'GB'];
    let size = bytes;
    let unitIndex = 0;

    while (size >= 1024 && unitIndex < units.length - 1) {
      size /= 1024;
      unitIndex++;
    }

    return `${size.toFixed(2)} ${units[unitIndex]}`;
  }

  static getModifiedDate(caminho) {
    try {
      if (!fs.existsSync(caminho)) return null;
      return fs.statSync(caminho).mtime;
    } catch {
      return null;
    }
  }

  static getModifiedTimestamp(caminho) {
    try {
      if (!fs.existsSync(caminho)) return 0;
      return fs.statSync(caminho).mtimeMs;
    } catch {
      return 0;
    }
  }

  static validateMultiple(caminhos) {
    const resultado = {
      total: caminhos.length,
      validos: 0,
      invalidos: 0,
      ausentes: 0,
      detalhes: []
    };

    for (const caminho of caminhos) {
      if (!FileValidator.exists(caminho)) {
        resultado.ausentes++;
        resultado.detalhes.push({ caminho, status: 'ausente' });
      } else if (!FileValidator.isValid(caminho)) {
        resultado.invalidos++;
        resultado.detalhes.push({ caminho, status: 'vazio' });
      } else {
        resultado.validos++;
        resultado.detalhes.push({ 
          caminho, 
          status: 'ok',
          tamanho: FileValidator.getSizeFormatted(caminho)
        });
      }
    }

    return resultado;
  }
}

/**
 * DiskMonitor - Monitoramento de espaço em disco
 */
class DiskMonitor {
  static verificarEspaco(caminho) {
    try {
      const result = execSync(`df -B1 "${caminho}" 2>/dev/null | tail -1`, { 
        encoding: 'utf8',
        timeout: 5000 
      });
      const partes = result.trim().split(/\s+/);

      if (partes.length >= 4) {
        const total = parseInt(partes[1], 10);
        const usado = parseInt(partes[2], 10);
        const livre = parseInt(partes[3], 10);
        const percentUsado = Math.round((usado / total) * 100);

        return { 
          total, usado, livre, percentUsado,
          livreGB: (livre / (1024 * 1024 * 1024)).toFixed(2),
          totalGB: (total / (1024 * 1024 * 1024)).toFixed(2)
        };
      }
    } catch (e) {}
    return null;
  }

  static temEspacoSuficiente(caminho, necessarioBytes) {
    const espaco = DiskMonitor.verificarEspaco(caminho);

    if (!espaco) {
      return { suficiente: true, verificado: false };
    }

    const suficiente = espaco.livre >= necessarioBytes;
    const necessarioGB = (necessarioBytes / (1024 * 1024 * 1024)).toFixed(2);

    return {
      suficiente,
      verificado: true,
      livreGB: espaco.livreGB,
      necessarioGB,
      percentUsado: espaco.percentUsado
    };
  }

  static calcularAjusteCRF(caminho) {
    if (!CONFIG.disco.compressaoAdaptativa.habilitado) {
      return 0;
    }

    const espaco = DiskMonitor.verificarEspaco(caminho);
    if (!espaco) return 0;

    const { percentUsado } = espaco;
    const { limiar85, limiar90, limiar95 } = CONFIG.disco.compressaoAdaptativa;

    if (percentUsado >= 95) {
      console.log(`⚠️ Disco ${percentUsado}% cheio → CRF +${limiar95}`);
      return limiar95;
    } else if (percentUsado >= 90) {
      console.log(`⚠️ Disco ${percentUsado}% cheio → CRF +${limiar90}`);
      return limiar90;
    } else if (percentUsado >= 85) {
      console.log(`⚠️ Disco ${percentUsado}% cheio → CRF +${limiar85}`);
      return limiar85;
    }

    return 0;
  }

  static verificarAlerta(caminho) {
    const espaco = DiskMonitor.verificarEspaco(caminho);
    if (!espaco) return null;

    if (espaco.percentUsado >= CONFIG.disco.alertaPercentual) {
      return {
        tipo: 'DISCO_CHEIO',
        percentUsado: espaco.percentUsado,
        livreGB: espaco.livreGB,
        mensagem: `⚠️ ALERTA: Disco ${espaco.percentUsado}% cheio!`
      };
    }

    return null;
  }
}

/**
 * AtomicWriter - Escrita atômica de arquivos (evita corrupção)
 */
class AtomicWriter {
  static escrever(caminho, conteudo, opcoes = {}) {
    const tempPath = `${caminho}.tmp.${Date.now()}`;

    try {
      let dados;
      if (opcoes.json || typeof conteudo === 'object') {
        dados = JSON.stringify(conteudo, null, opcoes.indent || 2);
      } else {
        dados = conteudo;
      }

      fs.writeFileSync(tempPath, dados, 'utf8');

      if (!FileValidator.isValid(tempPath)) {
        throw new Error('Arquivo temporário inválido');
      }

      fs.renameSync(tempPath, caminho);
      return true;
    } catch (e) {
      try { if (fs.existsSync(tempPath)) fs.unlinkSync(tempPath); } catch {}
      return false;
    }
  }

  static escreverJSON(caminho, objeto, indent = 2) {
    return AtomicWriter.escrever(caminho, objeto, { json: true, indent });
  }
}

/**
 * WebhookNotifier - Sistema de notificações HTTP
 */
class WebhookNotifier {
  constructor() {
    this.habilitado = CONFIG.webhook.habilitado;
  }

  async enviar(evento, dados) {
    if (!this.habilitado) return { enviado: false };
    if (!CONFIG.webhook.eventos[evento]) return { enviado: false };

    try {
      const http = CONFIG.webhook.url.startsWith('https') ? require('https') : require('http');
      const url = new URL(CONFIG.webhook.url);

      const payload = JSON.stringify({
        evento,
        timestamp: new Date().toISOString(),
        ...dados
      });

      return new Promise((resolve) => {
        const req = http.request({
          hostname: url.hostname,
          port: url.port || (url.protocol === 'https:' ? 443 : 80),
          path: url.pathname,
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          timeout: CONFIG.webhook.timeout
        }, (res) => {
          resolve({ enviado: true, status: res.statusCode });
        });

        req.on('error', () => resolve({ enviado: false }));
        req.on('timeout', () => { req.destroy(); resolve({ enviado: false }); });
        req.write(payload);
        req.end();
      });
    } catch {
      return { enviado: false };
    }
  }

  async notificarInicio(obra, idioma, totalVideos) {
    await this.enviar('inicio', { obra, idioma, totalVideos });
  }

  async notificarConclusao(obra, idioma, resultado) {
    await this.enviar('conclusao', { obra, idioma, sucesso: resultado.sucesso });
  }

  async notificarErro(obra, idioma, erro) {
    await this.enviar('erro', { obra, idioma, erro: String(erro) });
  }

  async notificarAlerta(tipo, dados) {
    await this.enviar('alerta', { tipo, ...dados });
  }
}

/**
 * 🆕 v2.6: ReportGenerator - Geração de relatórios detalhados
 */
class ReportGenerator {
  constructor(obra, idioma) {
    this.obra = obra;
    this.idioma = idioma;
    this.inicio = new Date();
    this.logs = [];
    this.estatisticas = {
      videosProcessados: 0,
      videosIgnorados: 0,
      videosQuarentena: 0,
      erros: [],
      avisos: []
    };
  }

  log(mensagem, tipo = 'info') {
    const timestamp = new Date().toISOString().slice(11, 19);
    this.logs.push({ timestamp, tipo, mensagem });

    const prefixos = {
      info: '📝',
      success: '✅',
      warning: '⚠️',
      error: '❌',
      section: '═══'
    };

    console.log(`${prefixos[tipo] || '•'} [${timestamp}] ${mensagem}`);
  }

  section(titulo) {
    console.log(`\n${'═'.repeat(60)}`);
    console.log(`   ${titulo.toUpperCase()}`);
    console.log(`${'═'.repeat(60)}`);
    this.logs.push({ timestamp: new Date().toISOString().slice(11, 19), tipo: 'section', mensagem: titulo });
  }

  error(mensagem, detalhes = null) {
    this.estatisticas.erros.push({ mensagem, detalhes, timestamp: new Date() });
    this.log(mensagem, 'error');
  }

  warning(mensagem) {
    this.estatisticas.avisos.push({ mensagem, timestamp: new Date() });
    this.log(mensagem, 'warning');
  }

  gerarRelatorioTexto(resultado) {
    const fim = new Date();
    const duracao = Math.round((fim - this.inicio) / 1000);

    const linhas = [];

    linhas.push('╔' + '═'.repeat(70) + '╗');
    linhas.push('║' + ' RELATÓRIO DE MERGE v2.6 '.padStart(47).padEnd(70) + '║');
    linhas.push('╠' + '═'.repeat(70) + '╣');

    linhas.push(`║  Obra: ${this.obra}`.padEnd(71) + '║');
    linhas.push(`║  Idioma: ${this.idioma}`.padEnd(71) + '║');
    linhas.push(`║  Data: ${this.inicio.toISOString()}`.padEnd(71) + '║');
    linhas.push(`║  Duração: ${duracao}s (${Math.floor(duracao/60)}m ${duracao%60}s)`.padEnd(71) + '║');

    linhas.push('╠' + '═'.repeat(70) + '╣');

    if (resultado.sucesso) {
      linhas.push('║  ✅ SUCESSO'.padEnd(71) + '║');
      linhas.push(`║  Modo: ${resultado.modo || 'COMPLETO'}`.padEnd(71) + '║');
      linhas.push(`║  Vídeos: ${resultado.totalVideos || 'N/A'}`.padEnd(71) + '║');
      linhas.push(`║  Tamanho: ${resultado.tamanhoMB || 'N/A'} MB`.padEnd(71) + '║');

      if (resultado.videosQuarentena > 0) {
        linhas.push(`║  ⚠️ Quarentena: ${resultado.videosQuarentena} vídeos`.padEnd(71) + '║');
      }
    } else {
      linhas.push('║  ❌ FALHA'.padEnd(71) + '║');
      linhas.push(`║  Erro: ${(resultado.erro || 'Desconhecido').slice(0, 55)}`.padEnd(71) + '║');
    }

    if (this.estatisticas.avisos.length > 0) {
      linhas.push('╠' + '═'.repeat(70) + '╣');
      linhas.push(`║  AVISOS: ${this.estatisticas.avisos.length}`.padEnd(71) + '║');
      for (const aviso of this.estatisticas.avisos.slice(0, 5)) {
        linhas.push(`║    - ${aviso.mensagem.slice(0, 60)}`.padEnd(71) + '║');
      }
    }

    linhas.push('╚' + '═'.repeat(70) + '╝');

    return linhas.join('\n');
  }

  salvar(pastaDestino, resultado) {
    if (!CONFIG.relatorios?.habilitado) return null;

    const timestamp = Date.now();
    const arquivos = {};

    // TXT
    if (CONFIG.relatorios.gerarTXT) {
      const txtPath = path.join(pastaDestino, `merge_report_${timestamp}.txt`);
      AtomicWriter.escrever(txtPath, this.gerarRelatorioTexto(resultado));
      arquivos.txt = txtPath;
    }

    // JSON
    if (CONFIG.relatorios.gerarJSON) {
      const jsonPath = path.join(pastaDestino, `merge_report_${timestamp}.json`);
      AtomicWriter.escreverJSON(jsonPath, {
        obra: this.obra,
        idioma: this.idioma,
        inicio: this.inicio.toISOString(),
        fim: new Date().toISOString(),
        resultado,
        estatisticas: this.estatisticas,
        logs: CONFIG.relatorios.incluirDetalhes ? this.logs : undefined
      });
      arquivos.json = jsonPath;
    }

    console.log(`📄 Relatório salvo`);
    return arquivos;
  }
}

/**
 * 🆕 v2.6: SystemMonitor - Monitoramento de RAM e CPU
 */
class SystemMonitor {
  constructor() {
    this.amostras = [];
    this.intervalo = null;
    this.inicio = null;
    this.cpuAnterior = null;
  }

  iniciar() {
    if (!CONFIG.monitoramento?.habilitado) return;

    this.inicio = Date.now();
    this.amostras = [];
    this.cpuAnterior = this.lerCPU();

    this.intervalo = setInterval(() => {
      this.coletar();
    }, CONFIG.monitoramento.intervaloMs || 5000);

    console.log('📊 Monitor de sistema iniciado');
  }

  parar() {
    if (this.intervalo) {
      clearInterval(this.intervalo);
      this.intervalo = null;
    }
  }

  lerCPU() {
    try {
      const stat = fs.readFileSync('/proc/stat', 'utf8');
      const linha = stat.split('\n')[0];
      const partes = linha.split(/\s+/).slice(1).map(Number);

      const idle = partes[3] + (partes[4] || 0);
      const total = partes.reduce((a, b) => a + b, 0);

      return { idle, total };
    } catch {
      return null;
    }
  }

  calcularUsoCPU() {
    const atual = this.lerCPU();
    if (!atual || !this.cpuAnterior) {
      this.cpuAnterior = atual;
      return 0;
    }

    const diffIdle = atual.idle - this.cpuAnterior.idle;
    const diffTotal = atual.total - this.cpuAnterior.total;

    this.cpuAnterior = atual;

    if (diffTotal === 0) return 0;

    return Math.round(((diffTotal - diffIdle) / diffTotal) * 1000) / 10;
  }

  lerRAM() {
    try {
      const meminfo = fs.readFileSync('/proc/meminfo', 'utf8');
      const linhas = meminfo.split('\n');

      const valores = {};
      for (const linha of linhas) {
        const match = linha.match(/^(\w+):\s+(\d+)/);
        if (match) {
          valores[match[1]] = parseInt(match[2], 10) * 1024;
        }
      }

      const total = valores.MemTotal || os.totalmem();
      const livre = (valores.MemFree || 0) + (valores.Buffers || 0) + (valores.Cached || 0);
      const usado = total - livre;
      const percentual = Math.round((usado / total) * 1000) / 10;

      return {
        total,
        totalGB: (total / (1024 * 1024 * 1024)).toFixed(2),
        usado,
        usadoGB: (usado / (1024 * 1024 * 1024)).toFixed(2),
        percentual
      };
    } catch {
      return null;
    }
  }

  coletar() {
    const ram = this.lerRAM();
    const cpu = this.calcularUsoCPU();

    const amostra = {
      timestamp: Date.now(),
      tempoDecorrido: Date.now() - this.inicio,
      ram: ram ? ram.percentual : 0,
      ramGB: ram ? parseFloat(ram.usadoGB) : 0,
      cpu
    };

    this.amostras.push(amostra);

    // Alertas
    if (ram && ram.percentual >= CONFIG.monitoramento.alertaRAM) {
      console.warn(`⚠️ ALERTA RAM: ${ram.percentual}%`);
    }

    if (cpu >= CONFIG.monitoramento.alertaCPU) {
      console.warn(`⚠️ ALERTA CPU: ${cpu}%`);
    }

    return amostra;
  }

  getEstatisticas() {
    if (this.amostras.length === 0) return null;

    const ramValues = this.amostras.map(a => a.ram);
    const cpuValues = this.amostras.map(a => a.cpu);
    const ramGBValues = this.amostras.map(a => a.ramGB);

    return {
      amostras: this.amostras.length,
      duracao: this.amostras.length > 0 
        ? this.amostras[this.amostras.length - 1].tempoDecorrido 
        : 0,
      ram: {
        min: Math.min(...ramValues),
        max: Math.max(...ramValues),
        media: Math.round(ramValues.reduce((a, b) => a + b, 0) / ramValues.length * 10) / 10,
        picoGB: Math.max(...ramGBValues)
      },
      cpu: {
        min: Math.min(...cpuValues),
        max: Math.max(...cpuValues),
        media: Math.round(cpuValues.reduce((a, b) => a + b, 0) / cpuValues.length * 10) / 10
      }
    };
  }

  mostrarResumo() {
    if (!CONFIG.monitoramento?.mostrarResumo) return;

    const stats = this.getEstatisticas();
    if (!stats) return;

    console.log('\n📊 ════════════════════════════════════════════');
    console.log('📊 ESTATÍSTICAS DE SISTEMA');
    console.log('📊 ════════════════════════════════════════════');
    console.log(`   Amostras: ${stats.amostras}`);
    console.log(`   RAM: min ${stats.ram.min}% | max ${stats.ram.max}% | média ${stats.ram.media}%`);
    console.log(`   CPU: min ${stats.cpu.min}% | max ${stats.cpu.max}% | média ${stats.cpu.media}%`);
    console.log('📊 ════════════════════════════════════════════\n');

    return stats;
  }

  salvarLog(pastaDestino) {
    if (!CONFIG.monitoramento?.salvarLog) return null;

    const stats = this.getEstatisticas();
    if (!stats) return null;

    const arquivo = path.join(pastaDestino, CONFIG.monitoramento.arquivoLog);
    AtomicWriter.escreverJSON(arquivo, {
      timestamp: new Date().toISOString(),
      estatisticas: stats,
      amostras: this.amostras
    });

    return arquivo;
  }
}

/**
 * CheckpointManager - Resume de onde parou
 */
class CheckpointManager {
  constructor(pastaCompilados) {
    this.pastaCompilados = pastaCompilados;
    this.checkpointPath = path.join(pastaCompilados, CONFIG.checkpoint.arquivoCheckpoint);
  }

  verificarRecuperacao() {
    if (!CONFIG.checkpoint.habilitado) {
      return { temCheckpoint: false };
    }

    if (FileValidator.isValid(this.checkpointPath)) {
      try {
        const dados = JSON.parse(fs.readFileSync(this.checkpointPath, 'utf8'));
        const idade = Date.now() - new Date(dados.timestamp).getTime();
        const idadeHoras = idade / (1000 * 60 * 60);

        if (idadeHoras > CONFIG.checkpoint.maxIdadeHoras) {
          console.log(`⚠️ Checkpoint muito antigo (${idadeHoras.toFixed(1)}h). Ignorando.`);
          this.limpar();
          return { temCheckpoint: false };
        }

        console.log(`\n🔄 CHECKPOINT ENCONTRADO`);
        console.log(`   Nível: ${dados.nivel}`);
        console.log(`   Arquivos: ${dados.arquivosProcessados}`);
        console.log(`   Idade: ${idadeHoras.toFixed(1)}h`);

        return { temCheckpoint: true, dados, idadeHoras };
      } catch {}
    }

    return { temCheckpoint: false };
  }

  salvarNivel(nivel, arquivosIntermediarios, totalOriginal) {
    if (!CONFIG.checkpoint.salvarPorNivel) return;

    const dados = {
      timestamp: new Date().toISOString(),
      nivel,
      arquivosProcessados: arquivosIntermediarios.length,
      totalOriginal,
      arquivosIntermediarios: arquivosIntermediarios.map(a => 
        typeof a === 'string' ? a : a.path
      )
    };

    AtomicWriter.escreverJSON(this.checkpointPath, dados);
  }

  limpar() {
    try {
      if (fs.existsSync(this.checkpointPath)) {
        fs.unlinkSync(this.checkpointPath);
      }
    } catch {}
  }
}

/**
 * QuarentenaManager - Isola vídeos problemáticos
 */
class QuarentenaManager {
  constructor(pastaBase) {
    this.pastaBase = pastaBase;
    this.pastaQuarentena = path.join(pastaBase, CONFIG.quarentena.pastaQuarentena);
    this.falhasPorVideo = new Map();
    this.videosEmQuarentena = [];
  }

  inicializar() {
    if (CONFIG.quarentena.habilitado && !fs.existsSync(this.pastaQuarentena)) {
      fs.mkdirSync(this.pastaQuarentena, { recursive: true });
    }
  }

  registrarFalha(video, erro) {
    if (!CONFIG.quarentena.habilitado) return false;

    const pagina = video.pageNum;
    const falhasAtuais = (this.falhasPorVideo.get(pagina) || 0) + 1;
    this.falhasPorVideo.set(pagina, falhasAtuais);

    if (falhasAtuais >= CONFIG.quarentena.maxFalhasAntesMover) {
      return this.moverParaQuarentena(video, erro);
    }

    return false;
  }

  moverParaQuarentena(video, erro) {
    try {
      const nomeArquivo = path.basename(video.path);
      const destino = path.join(this.pastaQuarentena, nomeArquivo);

      fs.renameSync(video.path, destino);

      this.videosEmQuarentena.push({
        pageNum: video.pageNum,
        arquivoOriginal: video.path,
        arquivoQuarentena: destino,
        erro,
        timestamp: new Date().toISOString()
      });

      if (CONFIG.quarentena.logMotivo) {
        const logPath = path.join(this.pastaQuarentena, `${video.pageNum}_motivo.txt`);
        fs.writeFileSync(logPath, `Página: ${video.pageNum}\nErro: ${erro}\nData: ${new Date().toISOString()}\n`);
      }

      console.log(`   🔒 Página ${video.pageNum} movida para QUARENTENA`);
      return true;
    } catch {
      return false;
    }
  }

  deveIgnorar(video) {
    const falhas = this.falhasPorVideo.get(video.pageNum) || 0;
    return falhas >= CONFIG.quarentena.maxFalhasAntesMover;
  }

  getTotal() {
    return this.videosEmQuarentena.length;
  }

  getRelatorio() {
    return {
      totalEmQuarentena: this.videosEmQuarentena.length,
      videos: this.videosEmQuarentena,
      pastaQuarentena: this.pastaQuarentena
    };
  }
}

/**
 * BackupManager - Backup e rollback automático
 */
class BackupManager {
  static gerenciarBackups(pastaCompilados, nomeBase) {
    if (!CONFIG.backup.habilitado) return null;

    try {
      const arquivos = fs.readdirSync(pastaCompilados);
      const prefixoBackup = `${nomeBase}${CONFIG.backup.sufixoBackup}`;

      const backups = arquivos
        .filter(arq => arq.startsWith(prefixoBackup) && arq.endsWith('.mp4'))
        .map(arq => ({
          nome: arq,
          caminho: path.join(pastaCompilados, arq),
          stat: fs.statSync(path.join(pastaCompilados, arq))
        }))
        .sort((a, b) => b.stat.mtimeMs - a.stat.mtimeMs);

      if (backups.length >= CONFIG.backup.maxBackups) {
        for (const backup of backups.slice(CONFIG.backup.maxBackups)) {
          try {
            fs.unlinkSync(backup.caminho);
            console.log(`   🗑️ Backup antigo removido: ${backup.nome}`);
          } catch {}
        }
      }

      return backups.length > 0 ? backups[0] : null;
    } catch {
      return null;
    }
  }

  static moverParaBackup(caminhoAtual, pastaCompilados, nomeBase) {
    if (!FileValidator.exists(caminhoAtual)) return null;
    if (!CONFIG.backup.habilitado) {
      try { fs.unlinkSync(caminhoAtual); } catch {}
      return null;
    }

    BackupManager.gerenciarBackups(pastaCompilados, nomeBase);

    const timestamp = Date.now();
    const nomeBackup = `${nomeBase}${CONFIG.backup.sufixoBackup}_${timestamp}.mp4`;
    const caminhoBackup = path.join(pastaCompilados, nomeBackup);

    try {
      const tamanhoOriginal = FileValidator.getSize(caminhoAtual);
      fs.renameSync(caminhoAtual, caminhoBackup);
      console.log(`   📦 Backup criado: ${nomeBackup}`);
      return { caminho: caminhoBackup, tamanho: tamanhoOriginal };
    } catch {
      return null;
    }
  }

  static verificarRollback(arquivoNovo, backupInfo) {
    if (!CONFIG.rollback.habilitado || !backupInfo) {
      return { deveRollback: false };
    }

    const tamanhoNovo = FileValidator.getSize(arquivoNovo);
    const tamanhoBackup = backupInfo.tamanho;

    if (tamanhoBackup === 0) return { deveRollback: false };

    const proporcao = tamanhoNovo / tamanhoBackup;

    if (CONFIG.rollback.logDetalhado) {
      console.log(`\n🔄 Verificação de Rollback:`);
      console.log(`   Novo: ${(tamanhoNovo / (1024*1024)).toFixed(2)} MB`);
      console.log(`   Backup: ${(tamanhoBackup / (1024*1024)).toFixed(2)} MB`);
      console.log(`   Proporção: ${(proporcao * 100).toFixed(1)}%`);
    }

    if (proporcao < CONFIG.rollback.limiarRollback) {
      console.error(`❌ ROLLBACK: Arquivo novo (${(proporcao * 100).toFixed(0)}%) muito menor!`);
      return { deveRollback: true, motivo: 'ARQUIVO_MUITO_PEQUENO', proporcao };
    }

    if (proporcao < CONFIG.rollback.limiarAlerta) {
      console.warn(`⚠️ ALERTA: Arquivo novo (${(proporcao * 100).toFixed(0)}%) menor que backup`);
    }

    return { deveRollback: false };
  }

  static executarRollback(arquivoNovo, backupInfo) {
    console.log(`\n🔄 EXECUTANDO ROLLBACK...`);

    try {
      if (FileValidator.exists(arquivoNovo)) {
        fs.unlinkSync(arquivoNovo);
      }

      fs.renameSync(backupInfo.caminho, arquivoNovo);
      console.log(`   ✅ Backup restaurado`);
      return true;
    } catch (e) {
      console.error(`   ❌ Erro no rollback: ${e.message}`);
      return false;
    }
  }
}

/**
 * GapDetector - Detecta páginas faltando na sequência
 */
class GapDetector {
  static detectar(videos) {
    if (!videos || videos.length === 0) {
      return { temGaps: false, gaps: [], sequenciaCompleta: true };
    }

    const numeros = videos.map(v => v.pageNum).sort((a, b) => a - b);
    const primeiro = numeros[0];
    const ultimo = numeros[numeros.length - 1];

    const gaps = [];
    for (let i = 0; i < numeros.length - 1; i++) {
      const atual = numeros[i];
      const proximo = numeros[i + 1];

      if (proximo - atual > 1) {
        for (let faltando = atual + 1; faltando < proximo; faltando++) {
          gaps.push(faltando);
        }
      }
    }

    return {
      temGaps: gaps.length > 0,
      gaps,
      totalGaps: gaps.length,
      primeiro,
      ultimo,
      total: videos.length
    };
  }

  static validar(videos, pastaDestino) {
    if (!CONFIG.validacoes.detectarGaps) {
      return { valido: true };
    }

    const resultado = GapDetector.detectar(videos);

    if (resultado.temGaps && CONFIG.validacoes.alertarGaps) {
      console.log(`\n⚠️ GAPS DETECTADOS: ${resultado.totalGaps} páginas faltando`);
      console.log(`   Faltando: [${resultado.gaps.slice(0, 10).join(', ')}${resultado.gaps.length > 10 ? '...' : ''}]`);

      if (CONFIG.validacoes.logPaginasFaltando) {
        const logPath = path.join(pastaDestino, 'paginas_faltando.log');
        fs.writeFileSync(logPath, `Páginas faltando: ${resultado.gaps.join(', ')}\n`);
      }
    }

    return {
      valido: CONFIG.validacoes.continuarComGaps || !resultado.temGaps,
      gaps: resultado.gaps,
      temGaps: resultado.temGaps
    };
  }
}

/**
 * Gerenciador de Capítulos para YouTube
 */
class ChapterManager {
  constructor() {
    this.capitulos = [];
    this.duracaoTotal = 0;
  }

  criarCapitulosFixos(videos, duracoes, intervalo) {
    if (!videos || videos.length === 0) return [];

    this.capitulos = [];
    let tempoAcumulado = 0;
    let capituloAtual = {
      inicio: 0,
      paginaInicio: videos[0].pageNum,
      timestampInicio: 0
    };

    for (let i = 0; i < videos.length; i++) {
      const video = videos[i];
      const duracao = duracoes[i] || 10;

      if (i > 0 && i % intervalo === 0) {
        capituloAtual.paginaFim = videos[i - 1].pageNum;
        capituloAtual.timestampFim = tempoAcumulado;
        capituloAtual.duracao = tempoAcumulado - capituloAtual.timestampInicio;
        this.capitulos.push({ ...capituloAtual });

        capituloAtual = {
          inicio: this.capitulos.length,
          paginaInicio: video.pageNum,
          timestampInicio: tempoAcumulado
        };
      }

      tempoAcumulado += duracao;
    }

    capituloAtual.paginaFim = videos[videos.length - 1].pageNum;
    capituloAtual.timestampFim = tempoAcumulado;
    capituloAtual.duracao = tempoAcumulado - capituloAtual.timestampInicio;
    this.capitulos.push(capituloAtual);

    this.duracaoTotal = tempoAcumulado;
    return this.capitulos;
  }

  formatarTimestamp(segundos) {
    const h = Math.floor(segundos / 3600);
    const m = Math.floor((segundos % 3600) / 60);
    const s = Math.floor(segundos % 60);

    if (h > 0) {
      return `${h}:${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}`;
    }
    return `${m}:${s.toString().padStart(2, '0')}`;
  }

  gerarTimestampsYouTube() {
    if (this.capitulos.length === 0) return '';

    const linhas = ['📑 CAPÍTULOS:', ''];

    for (let i = 0; i < this.capitulos.length; i++) {
      const cap = this.capitulos[i];
      const timestamp = this.formatarTimestamp(cap.timestampInicio);
      const nome = CONFIG.capitulos.nomeFormato
        .replace('{n}', i + 1)
        .replace('{inicio}', cap.paginaInicio)
        .replace('{fim}', cap.paginaFim);

      linhas.push(`${timestamp} ${nome}`);
    }

    return linhas.join('\n');
  }

  salvar(pastaDestino, nomeBase) {
    if (!CONFIG.capitulos.gerarArquivoTimestamps) return null;

    const timestampsPath = path.join(pastaDestino, `${nomeBase}_capitulos.txt`);
    fs.writeFileSync(timestampsPath, this.gerarTimestampsYouTube());
    console.log(`📑 Capítulos salvos: ${path.basename(timestampsPath)}`);

    const jsonPath = path.join(pastaDestino, `${nomeBase}_capitulos.json`);
    AtomicWriter.escreverJSON(jsonPath, {
      totalCapitulos: this.capitulos.length,
      duracaoTotal: this.duracaoTotal,
      duracaoFormatada: this.formatarTimestamp(this.duracaoTotal),
      capitulos: this.capitulos
    });

    return { txt: timestampsPath, json: jsonPath };
  }

  mostrarResumo() {
    console.log(`\n📑 CAPÍTULOS: ${this.capitulos.length} (${this.formatarTimestamp(this.duracaoTotal)})`);
  }
}

