/**
 * 🆕 v2.6: PadroesFalhaManager - Registro de erros para análise
 */
class PadroesFalhaManager {
  static registrar(pastaCompilados, erro, contexto = {}) {
    if (!CONFIG.padroesFalha.habilitado) return;

    const logPath = path.join(pastaCompilados, CONFIG.padroesFalha.arquivoLog);

    let registros = [];
    try {
      if (FileValidator.isValid(logPath)) {
        registros = JSON.parse(fs.readFileSync(logPath, 'utf8'));
      }
    } catch {}

    registros.push({
      timestamp: new Date().toISOString(),
      erro: String(erro).slice(0, 500),
      ...contexto
    });

    // Mantém apenas últimos N registros
    if (registros.length > CONFIG.padroesFalha.maxRegistros) {
      registros = registros.slice(-CONFIG.padroesFalha.maxRegistros);
    }

    AtomicWriter.escreverJSON(logPath, registros);
  }

  static analisar(pastaCompilados) {
    const logPath = path.join(pastaCompilados, CONFIG.padroesFalha.arquivoLog);

    if (!FileValidator.isValid(logPath)) return null;

    try {
      const registros = JSON.parse(fs.readFileSync(logPath, 'utf8'));

      // Agrupa por tipo de erro
      const porTipo = {};
      for (const reg of registros) {
        const tipo = reg.erro.split(':')[0] || 'DESCONHECIDO';
        porTipo[tipo] = (porTipo[tipo] || 0) + 1;
      }

      return {
        total: registros.length,
        porTipo,
        ultimoErro: registros[registros.length - 1]
      };
    } catch {
      return null;
    }
  }
}

/**
 * 🆕 v2.6: VideoDiagnostics - Diagnóstico de vídeos
 */
class VideoDiagnostics {
  static analisarVideo(caminhoVideo) {
    try {
      const resultado = execSync(
        `ffprobe -v error -select_streams v:0 -show_entries stream=width,height,r_frame_rate,codec_name,pix_fmt -of json "${caminhoVideo}"`,
        { encoding: 'utf8', timeout: 10000 }
      );

      const parsed = JSON.parse(resultado);
      const stream = parsed.streams?.[0] || {};

      let fps = 25;
      if (stream.r_frame_rate) {
        const [num, den] = stream.r_frame_rate.split('/');
        fps = Math.round((parseInt(num) / parseInt(den)) * 100) / 100;
      }

      return {
        width: stream.width || 0,
        height: stream.height || 0,
        fps,
        codec: stream.codec_name || 'unknown',
        pixFmt: stream.pix_fmt || 'unknown',
        detectado: true
      };
    } catch {
      return { detectado: false };
    }
  }

  static diagnosticarGrupo(caminhos, grupoId) {
    if (!CONFIG.debug?.diagnosticarVideos) return null;

    console.log(`\n   🔬 DIAGNÓSTICO DO GRUPO ${grupoId} (${caminhos.length} vídeos)`);
    console.log(`   ${'─'.repeat(60)}`);

    const diagnostico = {
      grupo: grupoId,
      totalVideos: caminhos.length,
      timestamp: new Date().toISOString(),
      videos: [],
      resumo: {}
    };

    const resolucoes = new Set();
    const framerates = new Set();
    const codecs = new Set();

    for (let i = 0; i < Math.min(caminhos.length, 5); i++) {
      const caminho = typeof caminhos[i] === 'string' ? caminhos[i] : caminhos[i].path;
      const info = VideoDiagnostics.analisarVideo(caminho);

      if (info.detectado) {
        diagnostico.videos.push({ indice: i, ...info });
        resolucoes.add(`${info.width}x${info.height}`);
        framerates.add(info.fps);
        codecs.add(info.codec);

        console.log(`   [${i}] ${path.basename(caminho)}: ${info.width}x${info.height} @ ${info.fps}fps (${info.codec})`);
      }
    }

    if (caminhos.length > 5) {
      console.log(`   ... e mais ${caminhos.length - 5} vídeos`);
    }

    diagnostico.resumo = {
      resolucoesUnicas: Array.from(resolucoes),
      frameratesUnicos: Array.from(framerates),
      codecsUnicos: Array.from(codecs),
      todasResolucoesIguais: resolucoes.size === 1,
      todosFrameratesIguais: framerates.size === 1
    };

    console.log(`   ${'─'.repeat(60)}`);
    console.log(`   📊 Resoluções: ${Array.from(resolucoes).join(', ')} ${resolucoes.size > 1 ? '⚠️' : '✅'}`);
    console.log(`   📊 Framerates: ${Array.from(framerates).join(', ')} ${framerates.size > 1 ? '⚠️' : '✅'}`);

    return diagnostico;
  }
}

/**
 * 🆕 v2.6: ConfigManager - Cache de configuração com histórico
 */
class ConfigManager {
  constructor(configPath) {
    this.configPath = configPath;
    this.config = this.load();
  }

  load() {
    try {
      if (fs.existsSync(this.configPath)) {
        return JSON.parse(fs.readFileSync(this.configPath, 'utf8'));
      }
    } catch {}
    return {};
  }

  save(data) {
    try {
      const merged = { ...this.config, ...data, lastUpdated: new Date().toISOString() };
      fs.writeFileSync(this.configPath, JSON.stringify(merged, null, 2));
      this.config = merged;
      return true;
    } catch {
      return false;
    }
  }

  getOptimalBatchSize(defaultSize) {
    return this.config.optimalBatchSize || defaultSize;
  }

  recordSuccess(batchSize, totalVideos, duration, pesoObservado = null) {
    const data = {
      optimalBatchSize: batchSize,
      lastSuccessfulMerge: { 
        batchSize, totalVideos, 
        durationSeconds: duration, 
        timestamp: new Date().toISOString() 
      }
    };

    // 🆕 v2.7: Peso observado para cálculos futuros
    if (pesoObservado) {
      data.pesoObservado = pesoObservado;
    }

    this.save(data);
  }

  recordFailure(batchSize, error) {
    const failures = this.config.failures || [];
    failures.push({ batchSize, error: error.substring(0, 200), timestamp: new Date().toISOString() });
    if (failures.length > 10) failures.shift();
    this.save({ failures });
  }

  // 🆕 v2.6: Estimativa de tempo baseada em histórico
  estimarTempo(totalVideos) {
    if (this.config.lastSuccessfulMerge?.totalVideos && this.config.lastSuccessfulMerge?.durationSeconds) {
      const videosAnterior = this.config.lastSuccessfulMerge.totalVideos;
      const tempoAnterior = this.config.lastSuccessfulMerge.durationSeconds;
      const tempoPorVideo = tempoAnterior / videosAnterior;
      const tempoEstimado = Math.ceil(tempoPorVideo * totalVideos);

      return {
        tempoEstimadoSegundos: tempoEstimado,
        tempoEstimadoMinutos: Math.ceil(tempoEstimado / 60),
        baseadoEm: `${videosAnterior} vídeos em ${tempoAnterior}s`,
        confianca: 'alta'
      };
    }

    // Estimativa padrão
    const tempoPorVideo = 3;
    const tempoEstimado = Math.ceil(tempoPorVideo * totalVideos);

    return {
      tempoEstimadoSegundos: tempoEstimado,
      tempoEstimadoMinutos: Math.ceil(tempoEstimado / 60),
      baseadoEm: 'estimativa padrão (3s/vídeo)',
      confianca: 'baixa'
    };
  }

  // 🆕 v2.7: Calcula parâmetros otimizados baseado em recursos e cache
  calcularParametros(analiseArquivos) {
    const cpus = os.cpus().length;
    const memoriaBytes = os.totalmem();
    const memoriaGB = Math.floor(memoriaBytes / (1024 * 1024 * 1024));
    const fatorUso = CONFIG.concorrencia?.fatorUso || 0.7;

    const ramDisponivel = memoriaGB * fatorUso;
    const ramDisponivelMB = ramDisponivel * 1024;

    // Usa peso do cache se disponível
    let pesoEstimadoMB;
    if (this.config.pesoObservado?.ramPorArquivoMB) {
      pesoEstimadoMB = this.config.pesoObservado.ramPorArquivoMB;
      console.log(`   💾 Usando peso do cache: ${pesoEstimadoMB.toFixed(2)} MB/arquivo`);
    } else {
      const fatorFps = (analiseArquivos.fps || 25) / 25;
      const fatorRes = ((analiseArquivos.width || 1920) * (analiseArquivos.height || 1080)) / (1920 * 1080);
      const overhead = 4;
      pesoEstimadoMB = (analiseArquivos.tamanhoMB || 50) * fatorFps * fatorRes * overhead;
      console.log(`   📊 Peso estimado: ${pesoEstimadoMB.toFixed(2)} MB/arquivo`);
    }

    // Calcula concorrência
    let concorrencia = CONFIG.concorrencia?.maxParalelo || 4;
    if (CONFIG.concorrencia?.autoDetect) {
      concorrencia = Math.max(1, Math.floor(cpus * fatorUso));
      concorrencia = Math.min(concorrencia, CONFIG.concorrencia?.maxParalelo || 4);
    }

    // Calcula arquivos por nível
    const ramPorProcesso = ramDisponivelMB / concorrencia;
    let arquivosPorNivel = Math.floor(ramPorProcesso / pesoEstimadoMB);
    arquivosPorNivel = Math.max(CONFIG.hierarchy?.minBatchSize || 5, arquivosPorNivel);
    arquivosPorNivel = Math.min(50, arquivosPorNivel);

    console.log(`\n📐 Parâmetros calculados:`);
    console.log(`   CPUs: ${cpus} | RAM: ${memoriaGB}GB`);
    console.log(`   Concorrência: ${concorrencia}`);
    console.log(`   Arquivos/nível: ${arquivosPorNivel}`);

    return {
      arquivosPorNivel,
      concorrencia,
      pesoEstimadoMB
    };
  }
}

/**
 * 🆕 v2.6: MudancasDetector - Verifica mudanças entre execuções
 */
class MudancasDetector {
  static gerarHashLista(videosInfo) {
    const str = videosInfo
      .map(v => `${v.pageNum}:${v.tamanho}:${v.modificadoTimestamp}`)
      .sort()
      .join('|');

    return crypto.createHash('md5').update(str).digest('hex');
  }

  static coletarInfoVideos(videos) {
    return videos.map(v => {
      try {
        const stats = fs.statSync(v.path);
        return {
          pageNum: v.pageNum,
          arquivo: path.basename(v.path),
          tamanho: stats.size,
          modificadoEm: stats.mtime.toISOString(),
          modificadoTimestamp: stats.mtimeMs
        };
      } catch {
        return {
          pageNum: v.pageNum,
          arquivo: path.basename(v.path),
          tamanho: 0,
          modificadoTimestamp: Date.now()
        };
      }
    });
  }

  static verificarMudancas(videos, metaPath) {
    const resultado = {
      mudou: true,
      motivo: 'PRIMEIRA_EXECUCAO',
      detalhes: {
        paginasNovas: [],
        paginasRemovidas: [],
        paginasModificadas: [],
        totalAntes: 0,
        totalAgora: videos.length
      }
    };

    if (!FileValidator.isValid(metaPath)) {
      return resultado;
    }

    let metaAntigo;
    try {
      metaAntigo = JSON.parse(fs.readFileSync(metaPath, 'utf8'));
    } catch {
      resultado.motivo = 'ERRO_LER_METADADOS';
      return resultado;
    }

    if (!metaAntigo.cache || !metaAntigo.cache.videosUsados) {
      resultado.motivo = 'METADADOS_SEM_CACHE';
      return resultado;
    }

    const cacheAntigo = metaAntigo.cache;
    resultado.detalhes.totalAntes = cacheAntigo.videosUsados.length;

    const videosAntigosMap = new Map();
    for (const v of cacheAntigo.videosUsados) {
      videosAntigosMap.set(v.pageNum, v);
    }

    const videosAtuaisInfo = MudancasDetector.coletarInfoVideos(videos);
    const videosAtuaisMap = new Map();
    for (const v of videosAtuaisInfo) {
      videosAtuaisMap.set(v.pageNum, v);
    }

    // Novas
    for (const pageNum of videosAtuaisMap.keys()) {
      if (!videosAntigosMap.has(pageNum)) {
        resultado.detalhes.paginasNovas.push(pageNum);
      }
    }

    // Removidas
    for (const pageNum of videosAntigosMap.keys()) {
      if (!videosAtuaisMap.has(pageNum)) {
        resultado.detalhes.paginasRemovidas.push(pageNum);
      }
    }

    // Modificadas
    for (const [pageNum, infoAtual] of videosAtuaisMap) {
      const infoAntigo = videosAntigosMap.get(pageNum);
      if (infoAntigo) {
        if (infoAntigo.tamanho !== infoAtual.tamanho || 
            infoAntigo.modificadoTimestamp !== infoAtual.modificadoTimestamp) {
          resultado.detalhes.paginasModificadas.push(pageNum);
        }
      }
    }

    const temNovas = resultado.detalhes.paginasNovas.length > 0;
    const temRemovidas = resultado.detalhes.paginasRemovidas.length > 0;
    const temModificadas = resultado.detalhes.paginasModificadas.length > 0;

    if (!temNovas && !temRemovidas && !temModificadas) {
      resultado.mudou = false;
      resultado.motivo = 'SEM_MUDANCAS';
    } else if (temNovas && !temRemovidas && !temModificadas) {
      resultado.motivo = 'PAGINAS_NOVAS';
    } else if (temModificadas) {
      resultado.motivo = 'PAGINAS_MODIFICADAS';
    } else if (temRemovidas) {
      resultado.motivo = 'PAGINAS_REMOVIDAS';
    } else {
      resultado.motivo = 'MULTIPLAS_MUDANCAS';
    }

    return resultado;
  }

  static gerarRelatorioDiferencas(mudancas, pastaDestino) {
    if (!mudancas.mudou) return null;

    console.log('\n📊 ════════════════════════════════════════════');
    console.log('📊 RELATÓRIO DE DIFERENÇAS');
    console.log('📊 ════════════════════════════════════════════');

    const relatorio = {
      timestamp: new Date().toISOString(),
      totalAntes: mudancas.detalhes.totalAntes,
      totalAgora: mudancas.detalhes.totalAgora,
      diferenca: mudancas.detalhes.totalAgora - mudancas.detalhes.totalAntes,
      paginasNovas: mudancas.detalhes.paginasNovas,
      paginasRemovidas: mudancas.detalhes.paginasRemovidas,
      paginasModificadas: mudancas.detalhes.paginasModificadas
    };

    console.log(`   Vídeos antes: ${relatorio.totalAntes}`);
    console.log(`   Vídeos agora: ${relatorio.totalAgora}`);
    console.log(`   Diferença: ${relatorio.diferenca >= 0 ? '+' : ''}${relatorio.diferenca}`);

    if (relatorio.paginasNovas.length > 0) {
      console.log(`   ➕ Novas: [${relatorio.paginasNovas.slice(0, 10).join(', ')}${relatorio.paginasNovas.length > 10 ? '...' : ''}]`);
    }
    if (relatorio.paginasRemovidas.length > 0) {
      console.log(`   ➖ Removidas: [${relatorio.paginasRemovidas.slice(0, 10).join(', ')}${relatorio.paginasRemovidas.length > 10 ? '...' : ''}]`);
    }
    if (relatorio.paginasModificadas.length > 0) {
      console.log(`   ✏️ Modificadas: [${relatorio.paginasModificadas.slice(0, 10).join(', ')}${relatorio.paginasModificadas.length > 10 ? '...' : ''}]`);
    }

    console.log('📊 ════════════════════════════════════════════\n');

    // Salva relatório
    const relatorioPath = path.join(pastaDestino, `diferencas_${Date.now()}.json`);
    AtomicWriter.escreverJSON(relatorioPath, relatorio);

    return relatorio;
  }
}

