/**
 * 🆕 v2.7: AudioAnalyzer - Análise de áudio de vídeos
 */
class AudioAnalyzer {
  /**
   * Analisa informações de áudio de um vídeo
   */
  static analisarAudio(caminhoVideo) {
    try {
      const resultado = execSync(
        `ffprobe -v error -select_streams a:0 -show_entries stream=sample_rate,channels,codec_name,duration -of json "${caminhoVideo}"`,
        { encoding: 'utf8', timeout: CONFIG.timeouts?.ffprobeMs || 10000 }
      );

      const parsed = JSON.parse(resultado);
      const stream = parsed.streams?.[0] || {};

      return {
        sampleRate: parseInt(stream.sample_rate) || 0,
        channels: parseInt(stream.channels) || 0,
        codec: stream.codec_name || 'none',
        duracao: parseFloat(stream.duration) || 0,
        temAudio: !!stream.sample_rate,
        detectado: true
      };
    } catch {
      return { temAudio: false, detectado: false };
    }
  }

  /**
   * Verifica consistência de áudio entre vídeos
   */
  static verificarConsistencia(videos) {
    if (!CONFIG.validacoes?.consistenciaAudio?.habilitado) {
      return { consistente: true, verificado: false };
    }

    const amostraSize = Math.min(CONFIG.validacoes.consistenciaAudio.amostraVideos || 10, videos.length);

    // Distribui amostra
    const indices = [];
    for (let i = 0; i < amostraSize; i++) {
      indices.push(Math.floor(i * videos.length / amostraSize));
    }

    const sampleRates = new Set();
    const canais = new Set();
    const detalhes = [];

    for (const idx of indices) {
      const video = videos[idx];
      const audio = AudioAnalyzer.analisarAudio(video.path);

      if (audio.temAudio) {
        sampleRates.add(audio.sampleRate);
        canais.add(audio.channels);
        detalhes.push({
          pageNum: video.pageNum,
          sampleRate: audio.sampleRate,
          channels: audio.channels,
          codec: audio.codec
        });
      } else {
        detalhes.push({
          pageNum: video.pageNum,
          semAudio: true
        });
      }
    }

    const consistente = sampleRates.size <= 1 && canais.size <= 1;

    if (!consistente) {
      console.log(`\n⚠️ INCONSISTÊNCIA DE ÁUDIO DETECTADA:`);
      console.log(`   Sample rates: ${Array.from(sampleRates).join(', ')}`);
      console.log(`   Canais: ${Array.from(canais).join(', ')}`);
    }

    return {
      consistente,
      verificado: true,
      sampleRates: Array.from(sampleRates),
      canais: Array.from(canais),
      detalhes
    };
  }
}

/**
 * 🆕 v2.7: VideoAnalyzer - Análise completa de arquivos de vídeo
 */
class VideoAnalyzer {
  /**
   * Analisa um arquivo de vídeo completo
   */
  static analisarArquivo(caminhoVideo) {
    try {
      // Análise de vídeo
      const videoInfo = execSync(
        `ffprobe -v error -select_streams v:0 -show_entries stream=duration,r_frame_rate,width,height,codec_name -of json "${caminhoVideo}"`,
        { encoding: 'utf8', timeout: CONFIG.timeouts?.ffprobeMs || 10000 }
      );

      const video = JSON.parse(videoInfo);
      const vStream = video.streams?.[0] || {};

      // Análise de áudio
      const audioInfo = AudioAnalyzer.analisarAudio(caminhoVideo);

      let fps = 25;
      if (vStream.r_frame_rate) {
        const [num, den] = vStream.r_frame_rate.split('/');
        fps = Math.round((parseInt(num) / parseInt(den)) * 100) / 100;
      }

      const tamanho = FileValidator.getSize(caminhoVideo);

      return {
        tamanhoBytes: tamanho,
        tamanhoMB: tamanho / (1024 * 1024),
        duracao: parseFloat(vStream.duration) || 10,
        fps,
        width: vStream.width || 0,
        height: vStream.height || 0,
        codec: vStream.codec_name || 'unknown',
        audio: audioInfo,
        valido: true
      };
    } catch {
      return { valido: false };
    }
  }

  /**
   * Analisa amostra de arquivos e retorna médias
   */
  static analisarAmostra(videos, quantidade = 5) {
    console.log(`\n📊 Analisando amostra de ${Math.min(quantidade, videos.length)} arquivos...`);

    const indices = [];
    for (let i = 0; i < Math.min(quantidade, videos.length); i++) {
      indices.push(Math.floor(i * videos.length / quantidade));
    }

    const analises = [];

    for (const idx of indices) {
      const analise = VideoAnalyzer.analisarArquivo(videos[idx].path);
      if (analise.valido) {
        analises.push(analise);
      }
    }

    if (analises.length === 0) {
      return {
        tamanhoMB: 50,
        duracao: 10,
        fps: 25,
        width: 1920,
        height: 1080
      };
    }

    const media = {
      tamanhoMB: analises.reduce((s, a) => s + a.tamanhoMB, 0) / analises.length,
      duracao: analises.reduce((s, a) => s + a.duracao, 0) / analises.length,
      fps: analises.reduce((s, a) => s + a.fps, 0) / analises.length,
      width: Math.max(...analises.map(a => a.width)),
      height: Math.max(...analises.map(a => a.height))
    };

    console.log(`   Tamanho médio: ${media.tamanhoMB.toFixed(2)} MB`);
    console.log(`   Duração média: ${media.duracao.toFixed(2)}s`);
    console.log(`   FPS: ${media.fps.toFixed(0)}`);
    console.log(`   Resolução: ${media.width}x${media.height}`);

    return media;
  }
}

/**
 * 🆕 v2.7: PreMergeValidator - Validação pré-merge completa
 */
class PreMergeValidator {
  static validar(videos, pastaDestino) {
    if (!CONFIG.validacoes?.validacaoPreMerge?.habilitado) {
      return { valido: true, verificado: false };
    }

    console.log('\n🔍 ════════════════════════════════════════════');
    console.log('🔍 VALIDAÇÃO PRÉ-MERGE (v2.7)');
    console.log('🔍 ════════════════════════════════════════════');

    const config = CONFIG.validacoes.validacaoPreMerge;
    const amostraSize = Math.min(config.amostraVideos, videos.length);

    // Seleciona amostra distribuída
    const indices = [];
    for (let i = 0; i < amostraSize; i++) {
      indices.push(Math.floor(i * videos.length / amostraSize));
    }

    console.log(`   Analisando ${amostraSize} vídeos (distribuídos)...`);

    const resultados = {
      videos: [],
      inconsistencias: [],
      videosProblematicos: []
    };

    // Analisa primeiro vídeo como referência
    const refAnalise = VideoAnalyzer.analisarArquivo(videos[indices[0]].path);

    if (!refAnalise.valido) {
      console.log(`   ❌ Não foi possível analisar vídeo de referência`);
      return { valido: true, verificado: false };
    }

    const fpsRef = refAnalise.fps;
    const widthRef = refAnalise.width;
    const heightRef = refAnalise.height;
    const codecRef = refAnalise.codec;
    const sampleRateRef = refAnalise.audio?.sampleRate || 44100;

    // Analisa cada vídeo
    for (const idx of indices) {
      const video = videos[idx];
      const analise = VideoAnalyzer.analisarArquivo(video.path);

      if (!analise.valido) continue;

      resultados.videos.push({
        pageNum: video.pageNum,
        ...analise
      });

      const problemas = [];

      // Verifica FPS
      if (config.verificarFPS && Math.abs(analise.fps - fpsRef) > config.toleranciaFPS) {
        problemas.push(`FPS: ${analise.fps.toFixed(1)} (esperado: ${fpsRef.toFixed(1)})`);
      }

      // Verifica resolução
      if (config.verificarResolucao && (analise.width !== widthRef || analise.height !== heightRef)) {
        problemas.push(`Resolução: ${analise.width}x${analise.height} (esperado: ${widthRef}x${heightRef})`);
      }

      // Verifica codec
      if (config.verificarCodec && analise.codec !== codecRef) {
        problemas.push(`Codec: ${analise.codec} (esperado: ${codecRef})`);
      }

      // Verifica áudio
      if (config.verificarAudio) {
        if (!analise.audio?.temAudio) {
          problemas.push('SEM ÁUDIO');
        } else if (analise.audio.sampleRate !== sampleRateRef) {
          problemas.push(`Sample rate: ${analise.audio.sampleRate} (esperado: ${sampleRateRef})`);
        }
      }

      if (problemas.length > 0) {
        resultados.inconsistencias.push({
          pageNum: video.pageNum,
          problemas
        });
        resultados.videosProblematicos.push(video.pageNum);
      }
    }

    // Log dos resultados
    console.log(`   ✅ Vídeos consistentes: ${amostraSize - resultados.inconsistencias.length}`);

    if (resultados.inconsistencias.length > 0) {
      console.log(`   ⚠️ Inconsistências encontradas: ${resultados.inconsistencias.length}`);
      for (const inc of resultados.inconsistencias.slice(0, 5)) {
        console.log(`      Pág ${inc.pageNum}: ${inc.problemas.join(', ')}`);
      }
    }

    console.log(`   Referência: ${widthRef}x${heightRef} @ ${fpsRef.toFixed(0)}fps, ${codecRef}, ${sampleRateRef}Hz`);
    console.log('🔍 ════════════════════════════════════════════\n');

    return {
      valido: true, // Não bloqueia, apenas alerta
      verificado: true,
      referencia: { fps: fpsRef, width: widthRef, height: heightRef, codec: codecRef, sampleRate: sampleRateRef },
      inconsistencias: resultados.inconsistencias,
      videosProblematicos: resultados.videosProblematicos
    };
  }
}

/**
 * 🆕 v2.7: FinalValidator - Validação final do arquivo gerado
 */
class FinalValidator {
  static obterDuracaoVideo(videoPath) {
    try {
      const resultado = execSync(
        `ffprobe -v error -select_streams v:0 -show_entries stream=duration -of csv=p=0 "${videoPath}"`,
        { encoding: 'utf8', timeout: CONFIG.timeouts?.ffprobeMs || 10000 }
      ).trim();
      return parseFloat(resultado) || null;
    } catch {
      return null;
    }
  }

  static obterDuracaoAudio(videoPath) {
    try {
      const resultado = execSync(
        `ffprobe -v error -select_streams a:0 -show_entries stream=duration -of csv=p=0 "${videoPath}"`,
        { encoding: 'utf8', timeout: CONFIG.timeouts?.ffprobeMs || 10000 }
      ).trim();
      return parseFloat(resultado) || null;
    } catch {
      return null;
    }
  }

  static validar(videoPath, videosOriginais) {
    if (!CONFIG.validacoes?.validacaoFinal?.habilitado) {
      return { valido: true, verificado: false };
    }

    console.log('\n✅ ════════════════════════════════════════════');
    console.log('✅ VALIDAÇÃO FINAL (v2.7)');
    console.log('✅ ════════════════════════════════════════════');

    const resultado = {
      valido: true,
      verificado: true,
      problemas: []
    };

    // Verifica se arquivo existe e tem tamanho
    if (!FileValidator.isValid(videoPath)) {
      resultado.valido = false;
      resultado.problemas.push('Arquivo não existe ou está vazio');
      return resultado;
    }

    const tamanhoFinal = FileValidator.getSize(videoPath);
    console.log(`   Tamanho: ${FileValidator.getSizeFormatted(videoPath)}`);

    // Verifica tamanho mínimo esperado
    if (CONFIG.validacoes.validacaoFinal.verificarTamanhoMinimo) {
      let tamanhoEsperado = 0;
      for (const v of videosOriginais) {
        tamanhoEsperado += FileValidator.getSize(v.path);
      }

      const minimo = tamanhoEsperado * (CONFIG.validacoes.validacaoFinal.tamanhoMinimoPorcentagem / 100);

      if (tamanhoFinal < minimo) {
        resultado.problemas.push(`Tamanho ${(tamanhoFinal/1024/1024).toFixed(1)}MB menor que esperado (mín: ${(minimo/1024/1024).toFixed(1)}MB)`);
      }
    }

    // Verifica duração
    if (CONFIG.validacoes.validacaoFinal.verificarDuracao) {
      const duracaoVideo = FinalValidator.obterDuracaoVideo(videoPath);
      const duracaoAudio = FinalValidator.obterDuracaoAudio(videoPath);

      if (duracaoVideo) {
        console.log(`   Duração vídeo: ${duracaoVideo.toFixed(2)}s`);
      }
      if (duracaoAudio) {
        console.log(`   Duração áudio: ${duracaoAudio.toFixed(2)}s`);
      }

      if (!duracaoVideo || duracaoVideo < 1) {
        resultado.problemas.push('Duração do vídeo inválida ou muito curta');
      }
    }

    // Verifica se tem áudio
    if (CONFIG.validacoes.validacaoFinal.verificarAudio) {
      const audioInfo = AudioAnalyzer.analisarAudio(videoPath);
      if (!audioInfo.temAudio) {
        resultado.problemas.push('Arquivo sem trilha de áudio');
      } else {
        console.log(`   Áudio: ${audioInfo.sampleRate}Hz, ${audioInfo.channels} canais`);
      }
    }

    resultado.valido = resultado.problemas.length === 0;

    if (resultado.valido) {
      console.log(`   ✅ Arquivo validado com sucesso!`);
    } else {
      console.log(`   ❌ Problemas encontrados:`);
      for (const p of resultado.problemas) {
        console.log(`      - ${p}`);
      }
    }

    console.log('✅ ════════════════════════════════════════════\n');

    return resultado;
  }
}

/**
 * 🆕 v2.7: PostProcessor - Pós-processamento do vídeo
 */
class PostProcessor {
  /**
   * Corta vídeo na duração do áudio se diferença > limiar
   */
  static cortarNaDuracaoAudio(videoPath) {
    if (!CONFIG.posProcessamento?.cortarNaDuracaoAudio?.habilitado) {
      return { cortado: false, motivo: 'desabilitado' };
    }

    console.log('\n🔧 ════════════════════════════════════════════');
    console.log('🔧 PÓS-PROCESSAMENTO: SINCRONIZAÇÃO ÁUDIO/VÍDEO');
    console.log('🔧 ════════════════════════════════════════════');

    const duracaoAudio = FinalValidator.obterDuracaoAudio(videoPath);
    const duracaoVideo = FinalValidator.obterDuracaoVideo(videoPath);

    if (!duracaoAudio || !duracaoVideo) {
      console.log('⚠️ Não foi possível detectar durações, pulando');
      console.log('🔧 ════════════════════════════════════════════\n');
      return { cortado: false, motivo: 'durações não detectadas' };
    }

    const diferenca = duracaoVideo - duracaoAudio;

    console.log(`📊 Duração ÁUDIO: ${duracaoAudio.toFixed(2)}s`);
    console.log(`📊 Duração VÍDEO: ${duracaoVideo.toFixed(2)}s`);
    console.log(`📊 Diferença: ${diferenca.toFixed(2)}s`);

    const limiar = CONFIG.posProcessamento.cortarNaDuracaoAudio.limiarSegundos || 5;

    if (diferenca < limiar) {
      console.log(`✅ Diferença < ${limiar}s, vídeo OK`);
      console.log('🔧 ════════════════════════════════════════════\n');
      return { cortado: false, diferenca, motivo: 'diferença insignificante' };
    }

    console.log(`\n🔪 Cortando vídeo (diferença ${diferenca.toFixed(1)}s > limiar ${limiar}s)...`);

    const tempPath = videoPath.replace('.mp4', '_TEMP_CORTADO.mp4');

    const cmd = `ffmpeg -y -i "${videoPath}" ` +
      `-t ${duracaoAudio.toFixed(3)} ` +
      `-c:v copy -c:a copy ` +
      `-avoid_negative_ts make_zero ` +
      `"${tempPath}" 2>&1`;

    try {
      execSync(cmd, { timeout: 600000, maxBuffer: 50 * 1024 * 1024 });

      if (FileValidator.isValid(tempPath)) {
        fs.unlinkSync(videoPath);
        fs.renameSync(tempPath, videoPath);

        console.log(`✅ CORTE CONCLUÍDO! Removidos: ${diferenca.toFixed(2)}s`);
        console.log('🔧 ════════════════════════════════════════════\n');

        return { cortado: true, removido: diferenca };
      } else {
        throw new Error('Arquivo temporário inválido');
      }
    } catch (e) {
      try { fs.unlinkSync(tempPath); } catch {}
      console.log(`⚠️ Erro no corte: ${e.message}`);
      console.log('🔧 ════════════════════════════════════════════\n');
      return { cortado: false, erro: e.message };
    }
  }
}

