/**
 * 🆕 v2.8: Executa comando com nice/ionice para prioridade baixa
 */
function executarComPrioridade(comando, opcoes = {}) {
  const cfg = CONFIG.prioridade || {};

  let cmdFinal = comando;

  // Adiciona ionice se habilitado
  if (cfg.usarIonice) {
    const ioniceClass = cfg.ioniceClass || 3;
    cmdFinal = `ionice -c ${ioniceClass} ${cmdFinal}`;
  }

  // Adiciona nice se habilitado
  if (cfg.usarNice) {
    const niceLevel = cfg.niceLevel || 10;
    cmdFinal = `nice -n ${niceLevel} ${cmdFinal}`;
  }

  return execSync(cmdFinal, opcoes);
}

/**
 * 🆕 v2.8: Monta comando FFmpeg com prioridade baixa
 */
function montarComandoFFmpeg(args) {
  const cfg = CONFIG.prioridade || {};

  let prefixo = '';

  if (cfg.usarNice) {
    prefixo += `nice -n ${cfg.niceLevel || 10} `;
  }

  if (cfg.usarIonice) {
    prefixo += `ionice -c ${cfg.ioniceClass || 3} `;
  }

  return `${prefixo}ffmpeg ${args}`;
}

/**
 * 🆕 v2.8: CTAGenerator - Gerador de frases de engajamento
 */
class CTAGenerator {
  constructor() {
    this.frasesUsadas = new Set();
  }

  /**
   * Obtém frases do idioma correto
   */
  getFrasesIdioma(codigoIdioma) {
    return FRASES_ENGAJAMENTO[codigoIdioma] || 
           FRASES_ENGAJAMENTO[codigoIdioma.split('_')[0] + '_BR'] ||
           FRASES_ENGAJAMENTO[codigoIdioma.split('_')[0] + '_US'] ||
           FRASES_ENGAJAMENTO.EN_US;
  }

  /**
   * Seleciona uma categoria baseada nos pesos configurados
   */
  selecionarCategoria() {
    const cfg = CONFIG.cta;
    const categorias = [];
    const pesos = [];

    for (const [cat, habilitado] of Object.entries(cfg.categorias)) {
      if (habilitado) {
        categorias.push(cat);
        pesos.push(cfg.pesos[cat] || 1);
      }
    }

    if (categorias.length === 0) return 'likes';

    const totalPeso = pesos.reduce((a, b) => a + b, 0);
    let random = Math.random() * totalPeso;

    for (let i = 0; i < categorias.length; i++) {
      random -= pesos[i];
      if (random <= 0) return categorias[i];
    }

    return categorias[0];
  }

  /**
   * Seleciona uma frase aleatória de uma categoria
   */
  selecionarFrase(frases, categoria) {
    const cfg = CONFIG.cta;
    const listaFrases = frases[categoria] || frases.likes;

    if (!listaFrases || listaFrases.length === 0) return "👍 LIKE!";

    if (cfg.evitarRepeticao) {
      const disponiveis = listaFrases.filter(f => !this.frasesUsadas.has(f));
      if (disponiveis.length > 0) {
        const frase = disponiveis[Math.floor(Math.random() * disponiveis.length)];
        this.frasesUsadas.add(frase);
        return frase;
      }
      this.frasesUsadas.clear();
    }

    return listaFrases[Math.floor(Math.random() * listaFrases.length)];
  }

  /**
   * Seleciona um estilo visual
   */
  selecionarEstilo() {
    const cfg = CONFIG.cta;

    if (cfg.estilo === 'aleatorio') {
      const estilos = Object.keys(CTA_ESTILOS);
      return CTA_ESTILOS[estilos[Math.floor(Math.random() * estilos.length)]];
    }

    return CTA_ESTILOS[cfg.estilo] || CTA_ESTILOS.padrao;
  }

  /**
   * Gera um vídeo CTA de curta duração
   */
  gerarCTA(outputPath, codigoIdioma, index = 0) {
    const cfg = CONFIG.cta;
    const duracao = cfg.duracao || 1.2;

    const frases = this.getFrasesIdioma(codigoIdioma);
    const categoria = this.selecionarCategoria();
    const frase = this.selecionarFrase(frases, categoria);
    const estilo = this.selecionarEstilo();

    // Escapar texto para FFmpeg
    const textoEscapado = frase
      .replace(/'/g, "'\\''")
      .replace(/:/g, '\\:')
      .replace(/\\/g, '\\\\');

    const width = 1920;
    const height = 1080;
    const fps = 25;

    // Construir filtro de texto
    const filtroTexto = `drawtext=text='${textoEscapado}'` +
      `:fontfile=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf` +
      `:fontsize=${estilo.tamanho}` +
      `:fontcolor=${estilo.corTexto}` +
      `:borderw=3` +
      `:bordercolor=black` +
      `:x=(w-text_w)/2` +
      `:y=(h-text_h)/2` +
      `:alpha='if(lt(t,0.15),t/0.15,if(lt(t,${duracao - 0.15}),1,(${duracao}-t)/0.15))'`;

    // Gera som de notificação
    let audioInput = '-f lavfi -i "anullsrc=r=24000:cl=mono"';
    if (cfg.somNotificacao?.habilitado) {
      switch (cfg.somNotificacao.tipo) {
        case 'pop':
          audioInput = '-f lavfi -i "sine=frequency=800:duration=0.1,afade=t=out:st=0.05:d=0.05"';
          break;
        case 'ding':
          audioInput = '-f lavfi -i "sine=frequency=1200:duration=0.15,afade=t=out:st=0.08:d=0.07"';
          break;
        case 'whoosh':
          audioInput = '-f lavfi -i "anoisesrc=d=0.2:c=pink,afade=t=in:st=0:d=0.1,afade=t=out:st=0.1:d=0.1"';
          break;
      }
    }

    // ⚠️ CRÍTICO: Usar 24000Hz mono para compatibilidade com v2.0
    const cmd = montarComandoFFmpeg(
      `-y -f lavfi -i "color=c=${estilo.corFundo}:s=${width}x${height}:d=${duracao}" ` +
      `${audioInput} ` +
      `-filter_complex "[0:v]${filtroTexto},fade=t=in:st=0:d=0.15,fade=t=out:st=${duracao - 0.15}:d=0.15[v];[1:a]apad=whole_dur=${duracao},aresample=24000,pan=mono|c0=c0[a]" ` +
      `-map "[v]" -map "[a]" ` +
      `-c:v libx264 -preset ultrafast -crf 28 ` +
      `-c:a aac -ar 24000 -ac 1 -b:a 128k ` +
      `-r ${fps} -t ${duracao} ` +
      `"${outputPath}"`
    );

    try {
      execSync(cmd, { timeout: 30000, maxBuffer: 10 * 1024 * 1024 });

      if (FileValidator.isValid(outputPath)) {
        console.log(`   ✅ CTA gerado: "${frase.substring(0, 35)}..."`);
        return {
          sucesso: true,
          arquivo: outputPath,
          frase: frase,
          categoria: categoria,
          duracao: duracao
        };
      }
      return { sucesso: false, erro: 'Arquivo inválido' };
    } catch (e) {
      console.error(`   ❌ Erro ao gerar CTA: ${e.message}`);
      return { sucesso: false, erro: e.message };
    }
  }

  /**
   * Determina em quais posições inserir CTAs
   */
  determinarPosicoesCTA(totalVideos) {
    const cfg = CONFIG.cta;

    if (!cfg.habilitado || totalVideos < 5) return [];

    const posicoes = [];
    const min = cfg.frequencia.minVideosEntre || 4;
    const max = cfg.frequencia.maxVideosEntre || 8;
    const maxCTAs = cfg.maxCTAs || 8;

    let posicaoAtual = min;

    while (posicaoAtual < totalVideos - 2 && posicoes.length < maxCTAs) {
      posicoes.push(posicaoAtual);
      const intervalo = Math.floor(Math.random() * (max - min + 1)) + min;
      posicaoAtual += intervalo;
    }

    console.log(`   📢 ${posicoes.length} CTA(s) serão inseridos nas posições: ${posicoes.join(', ')}`);
    return posicoes;
  }

  /**
   * Gera todos os CTAs necessários
   */
  gerarTodosCTAs(tempDir, codigoIdioma, quantidade) {
    const ctas = [];

    console.log(`\n🎯 Gerando ${quantidade} CTAs para ${codigoIdioma}...`);

    for (let i = 0; i < quantidade; i++) {
      const outputPath = path.join(tempDir, `cta_${i}.mp4`);
      const resultado = this.gerarCTA(outputPath, codigoIdioma, i);

      if (resultado.sucesso) {
        ctas.push(resultado);
      }
    }

    console.log(`   ✅ ${ctas.length}/${quantidade} CTAs gerados com sucesso`);
    return ctas;
  }
}

/**
 * 🆕 v2.8: Trilha sonora melhorada com amix e fade
 */
class TrilhaSonoraMelhorada {
  /**
   * Adiciona trilha sonora com loop, fade e volume ajustado
   */
  static aplicar(videoPath, trilhaPath, outputPath) {
    const cfg = CONFIG.trilhaSonoraMelhorada || {};

    if (!cfg.habilitado) {
      return { aplicado: false, motivo: 'desabilitado' };
    }

    console.log('\n🎵 ════════════════════════════════════════════');
    console.log('🎵 TRILHA SONORA MELHORADA (v2.8)');
    console.log('🎵 ════════════════════════════════════════════');

    const volume = cfg.volume || 0.15;
    const fadeIn = cfg.fadeIn || 2.0;
    const fadeOut = cfg.fadeOut || 3.0;

    // Obtém duração do vídeo
    const duracaoVideo = FinalValidator.obterDuracaoVideo(videoPath);

    if (!duracaoVideo || duracaoVideo <= 0) {
      console.log('   ⚠️ Não foi possível obter duração do vídeo');
      return { aplicado: false, motivo: 'duração inválida' };
    }

    console.log(`   📊 Duração do vídeo: ${duracaoVideo.toFixed(1)}s`);
    console.log(`   🔊 Volume da trilha: ${(volume * 100).toFixed(0)}%`);
    console.log(`   🎚️ Fade in: ${fadeIn}s | Fade out: ${fadeOut}s`);

    const fadeOutStart = Math.max(0, duracaoVideo - fadeOut);

    // Filtro de áudio para a trilha
    const filtroTrilha = `volume=${volume},afade=t=in:st=0:d=${fadeIn},afade=t=out:st=${fadeOutStart}:d=${fadeOut}`;

    let cmd;

    if (cfg.usarAmix) {
      // Usa amix para mixar áudio original com trilha (melhor qualidade)
      cmd = montarComandoFFmpeg(
        `-y -i "${videoPath}" -stream_loop -1 -i "${trilhaPath}" ` +
        `-filter_complex "[1:a]${filtroTrilha}[trilha];[0:a][trilha]amix=inputs=2:duration=first:dropout_transition=2,aresample=24000,pan=mono|c0=c0[aout]" ` +
        `-map 0:v -map "[aout]" ` +
        `-c:v copy ` +
        `-c:a aac -ar 24000 -ac 1 -b:a 128k ` +
        `-shortest "${outputPath}"`
      );
    } else {
      // Método mais simples (usa amerge)
      cmd = montarComandoFFmpeg(
        `-y -i "${videoPath}" -stream_loop -1 -i "${trilhaPath}" ` +
        `-filter_complex "[1:a]${filtroTrilha}[trilha];[0:a][trilha]amerge=inputs=2,pan=mono|c0=c0+c1,aresample=24000[aout]" ` +
        `-map 0:v -map "[aout]" ` +
        `-c:v copy ` +
        `-c:a aac -ar 24000 -ac 1 -b:a 128k ` +
        `-shortest "${outputPath}"`
      );
    }

    try {
      execSync(cmd, { timeout: 600000, maxBuffer: 50 * 1024 * 1024 });

      if (FileValidator.isValid(outputPath)) {
        console.log(`   ✅ Trilha sonora adicionada com sucesso!`);
        console.log('🎵 ════════════════════════════════════════════\n');
        return { aplicado: true };
      }

      return { aplicado: false, motivo: 'arquivo inválido' };
    } catch (e) {
      console.log(`   ⚠️ Erro ao adicionar trilha: ${e.message}`);
      console.log('🎵 ════════════════════════════════════════════\n');
      return { aplicado: false, erro: e.message };
    }
  }
}

/**
 * 🆕 v2.7: Executa tarefas em paralelo com limite de concorrência
 */
async function executarEmParalelo(tarefas, limite) {
  if (!CONFIG.concorrencia?.habilitado || limite <= 1) {
    // Execução sequencial
    const resultados = [];
    for (const tarefa of tarefas) {
      resultados.push(await tarefa());
    }
    return resultados;
  }

  // Execução paralela
  const resultados = [];
  const emExecucao = [];

  for (const tarefa of tarefas) {
    const promise = tarefa().then(resultado => {
      emExecucao.splice(emExecucao.indexOf(promise), 1);
      return resultado;
    });

    emExecucao.push(promise);
    resultados.push(promise);

    if (emExecucao.length >= limite) {
      await Promise.race(emExecucao);
    }
  }

  return Promise.all(resultados);
}

