// SEÇÃO 3: FUNÇÕES DE DESCOBERTA E DETECÇÃO
// ══════════════════════════════════════════════════════════════════════════════

function descobrirObras() {
  console.log(`\n🔍 DESCOBRINDO OBRAS...`);

  const obras = [];

  for (const pastaRaiz of CONFIG.pastasRaiz) {
    if (!fs.existsSync(pastaRaiz)) continue;

    try {
      const itens = fs.readdirSync(pastaRaiz);

      for (const item of itens) {
        const caminhoObra = path.join(pastaRaiz, item);
        if (!fs.statSync(caminhoObra).isDirectory()) continue;
        if (item.startsWith('.') || item.startsWith('_')) continue;

        const temVideos = verificarSeTemVideos(caminhoObra);

        if (temVideos.total > 0) {
          obras.push({
            nome: item,
            caminho: caminhoObra,
            pastaRaiz: pastaRaiz,
            videos: temVideos
          });
          console.log(`   ✅ ${item} (${temVideos.total} vídeos)`);
        }
      }
    } catch {}
  }

  console.log(`   Total: ${obras.length} obra(s)\n`);
  return obras;
}

function verificarSeTemVideos(caminhoObra) {
  const resultado = { total: 0, porIdioma: {} };

  for (const idioma of CONFIG.idiomas.filter(i => i.ativo)) {
    const locais = obterLocaisBusca(caminhoObra, idioma);
    let count = 0;

    for (const local of locais) {
      if (!fs.existsSync(local)) continue;

      try {
        const arquivos = fs.readdirSync(local);
        count += arquivos.filter(f => CONFIG.padraoVideo.test(f)).length;
      } catch {}
    }

    if (count > 0) {
      resultado.porIdioma[idioma.pasta] = count;
      resultado.total += count;
    }
  }

  return resultado;
}

function obterLocaisBusca(caminhoObra, idiomaConfig) {
  const locais = [];

  if (idiomaConfig.is_root) {
    locais.push(caminhoObra);
    locais.push(path.join(caminhoObra, 'videos'));
  } else {
    locais.push(path.join(caminhoObra, idiomaConfig.pasta));
    locais.push(path.join(caminhoObra, idiomaConfig.pasta, 'videos'));
  }

  return locais;
}

function buscarPastaObra(nomeObra) {
  for (const pastaRaiz of CONFIG.pastasRaiz) {
    const caminho = path.join(pastaRaiz, nomeObra);
    if (fs.existsSync(caminho)) {
      console.log(`   ✅ Encontrada: ${caminho}`);
      return { nome: nomeObra, caminho, pastaRaiz };
    }
  }
  return null;
}

function detectarVideos(caminhoObra, idiomaConfig) {
  const videos = [];
  const paginasEncontradas = new Set();
  const locais = obterLocaisBusca(caminhoObra, idiomaConfig);

  for (const local of locais) {
    if (!fs.existsSync(local)) continue;

    try {
      const arquivos = fs.readdirSync(local);

      for (const arquivo of arquivos) {
        // Verifica sufixos para ignorar
        if (CONFIG.sufixosIgnorar.some(s => arquivo.toLowerCase().includes(s.toLowerCase()))) {
          continue;
        }

        const match = arquivo.match(CONFIG.padraoVideo);
        if (!match) continue;

        const numeroPagina = parseInt(match[1], 10);
        if (paginasEncontradas.has(numeroPagina)) continue;

        const caminhoCompleto = path.join(local, arquivo);

        try {
          const stats = fs.statSync(caminhoCompleto);
          if (stats.size < 1000) continue;

          videos.push({
            path: caminhoCompleto,
            filename: arquivo,
            pageNum: numeroPagina,
            size: stats.size,
            sizeMB: (stats.size / (1024 * 1024)).toFixed(2)
          });

          paginasEncontradas.add(numeroPagina);
        } catch {}
      }
    } catch {}
  }

  videos.sort((a, b) => a.pageNum - b.pageNum);
  return videos;
}

