// SEÇÃO 4: FUNÇÕES DE ANÁLISE
// ══════════════════════════════════════════════════════════════════════════════

function obterPropriedadesVideo(caminhoVideo) {
  try {
    const videoInfo = execSync(
      `ffprobe -v error -select_streams v:0 -show_entries stream=r_frame_rate,width,height -of json "${caminhoVideo}"`,
      { encoding: 'utf8', timeout: 10000 }
    );
    const video = JSON.parse(videoInfo);

    const audioInfo = execSync(
      `ffprobe -v error -select_streams a:0 -show_entries stream=sample_rate,channels -of json "${caminhoVideo}"`,
      { encoding: 'utf8', timeout: 10000 }
    );
    const audio = JSON.parse(audioInfo);

    const vStream = video.streams?.[0] || {};
    const aStream = audio.streams?.[0] || {};

    let fps = 25;
    if (vStream.r_frame_rate) {
      const [num, den] = vStream.r_frame_rate.split('/');
      fps = Math.round((parseInt(num) / parseInt(den)) * 100) / 100;
    }

    return {
      width: vStream.width || 0,
      height: vStream.height || 0,
      fps,
      sampleRate: parseInt(aStream.sample_rate) || 0,
      channels: parseInt(aStream.channels) || 0,
      temAudio: !!aStream.sample_rate
    };
  } catch {
    return null;
  }
}

function verificarEspacoDisco(caminho) {
  try {
    const resultado = execSync(`df -h "${caminho}" | tail -1`, { encoding: 'utf8' });
    const partes = resultado.trim().split(/\s+/);
    return {
      total: partes[1],
      usado: partes[2],
      disponivel: partes[3],
      percentUsado: partes[4]
    };
  } catch {
    return null;
  }
}

function verificarConsistencia(videos) {
  console.log(`\n🔍 VERIFICANDO CONSISTÊNCIA...`);

  const espacoDisco = verificarEspacoDisco(videos[0].path);
  if (espacoDisco) {
    console.log(`   💾 Disco: ${espacoDisco.disponivel} livres (${espacoDisco.percentUsado} usado)`);
  }

  // Analisa amostra
  const indices = [0, Math.floor(videos.length / 2), videos.length - 1];
  const amostras = [];

  for (const idx of indices) {
    const props = obterPropriedadesVideo(videos[idx].path);
    if (props) {
      amostras.push({ idx, ...props });
    }
  }

  if (amostras.length === 0) {
    return { consistente: true };
  }

  const ref = amostras[0];
  console.log(`   📊 Referência: ${ref.width}x${ref.height} @ ${ref.fps}fps, ${ref.sampleRate}Hz`);

  return { consistente: true, referencia: ref };
}

function obterDuracaoVideo(caminhoVideo) {
  try {
    const resultado = execSync(
      `ffprobe -v error -show_entries format=duration -of csv=p=0 "${caminhoVideo}"`,
      { encoding: 'utf8', timeout: 10000 }
    ).trim();

    const duracao = parseFloat(resultado);
    return duracao > 0 ? duracao : 10;
  } catch {
    return 10;
  }
}

function obterDuracoes(videos) {
  console.log(`   ⏱️ Obtendo durações...`);

  const duracoes = [];
  const amostragem = videos.length > 50;
  const intervalo = amostragem ? Math.floor(videos.length / 20) : 1;

  let duracaoMedia = 0;
  let amostras = 0;

  for (let i = 0; i < videos.length; i++) {
    if (amostragem && i % intervalo !== 0 && i !== videos.length - 1) {
      duracoes.push(null);
      continue;
    }

    const duracao = obterDuracaoVideo(videos[i].path);
    duracoes[i] = duracao;
    duracaoMedia += duracao;
    amostras++;
  }

  duracaoMedia = duracaoMedia / amostras;

  for (let i = 0; i < duracoes.length; i++) {
    if (duracoes[i] === null) {
      duracoes[i] = duracaoMedia;
    }
  }

  const total = duracoes.reduce((a, b) => a + b, 0);
  console.log(`   ⏱️ Duração total: ${Math.floor(total / 60)}min ${Math.floor(total % 60)}s`);

  return duracoes;
}

