function dividirEmGrupos(array, tamanho) {
  const grupos = [];
  for (let i = 0; i < array.length; i += tamanho) {
    grupos.push(array.slice(i, i + tamanho));
  }
  return grupos;
}

/**
 * ⚠️ FUNÇÃO CRÍTICA - NÃO ALTERAR
 * Faz merge de um grupo de vídeos usando concat demuxer
 * Garante sincronia com: -c:v copy -c:a aac -ar 24000 -ac 1
 */
function mergeGrupo(arquivos, outputPath, tempDir, grupoId) {
  const caminhos = arquivos.map(arq => typeof arq === 'string' ? arq : arq.path);
  const n = caminhos.length;

  // 🆕 v2.6: Log de progresso
  if (CONFIG.debug?.mostrarProgressoGrupo) {
    console.log(`\n   ┌─────────────────────────────────────────────`);
    console.log(`   │ 📁 GRUPO ${grupoId}: ${n} vídeos`);
  }

  if (n === 1) {
    fs.copyFileSync(caminhos[0], outputPath);
    const sucesso = fs.existsSync(outputPath) && fs.statSync(outputPath).size > 0;
    if (CONFIG.debug?.mostrarProgressoGrupo) {
      console.log(`   │ ${sucesso ? '✅ OK (cópia)' : '❌ FALHA'}`);
      console.log(`   └─────────────────────────────────────────────\n`);
    }
    return sucesso;
  }

  // 🆕 v2.6: Diagnóstico de vídeos se habilitado
  if (CONFIG.debug?.diagnosticarVideos) {
    VideoDiagnostics.diagnosticarGrupo(caminhos, grupoId);
  }

  // Verifica arquivos
  for (let i = 0; i < caminhos.length; i++) {
    if (!fs.existsSync(caminhos[i])) {
      throw new Error(`Arquivo não encontrado: ${caminhos[i]}`);
    }
  }

  // Cria arquivo de lista para concat demuxer
  const listFile = path.join(tempDir, `list_${grupoId}.txt`);
  const listContent = caminhos.map(p => `file '${p}'`).join('\n');
  fs.writeFileSync(listFile, listContent);

  const timeout = Math.min(Math.max(n * 10000, 60000), 600000);

  // ⚠️ COMANDO CRÍTICO - NÃO ALTERAR
  // -c:v copy: copia vídeo sem recodificar
  // -c:a aac -ar 24000 -ac 1: recodifica áudio para garantir consistência
  const cmd = `ffmpeg -y -f concat -safe 0 -i "${listFile}" ` +
    `-c:v copy ` +
    `-c:a aac -ar ${CONFIG.encoding.audioSampleRate} -ac ${CONFIG.encoding.audioChannels} -b:a ${CONFIG.encoding.audioBitrate} ` +
    `"${outputPath}" 2>&1`;

  // 🆕 v2.6: Log do comando se debug ativado
  if (CONFIG.debug?.mostrarComandoFFmpeg) {
    console.log(`   │ 🔧 CMD: ffmpeg -f concat ... -c:v copy -c:a aac -ar 24000`);
  }

  const startTime = Date.now();

  try {
    execSync(cmd, { timeout, maxBuffer: 50 * 1024 * 1024, encoding: 'utf8' });

    const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);

    if (fs.existsSync(listFile)) fs.unlinkSync(listFile);

    if (!fs.existsSync(outputPath)) {
      throw new Error('Arquivo de saída não criado');
    }

    const outputSize = fs.statSync(outputPath).size;
    if (outputSize < 1000) {
      throw new Error('Arquivo de saída muito pequeno');
    }

    const outputSizeMB = (outputSize / (1024 * 1024)).toFixed(2);

    if (CONFIG.debug?.mostrarProgressoGrupo) {
      console.log(`   │ ✅ OK em ${elapsed}s (${outputSizeMB} MB)`);
      console.log(`   └─────────────────────────────────────────────\n`);
    }

    return true;

  } catch (e) {
    if (fs.existsSync(listFile)) fs.unlinkSync(listFile);

    const erroMsg = e.message.substring(0, 200);

    if (CONFIG.debug?.mostrarProgressoGrupo) {
      console.log(`   │ ❌ ERRO: ${erroMsg.substring(0, 60)}`);
      console.log(`   └─────────────────────────────────────────────\n`);
    }

    // 🆕 v2.6: Salva log de erro
    if (CONFIG.debug?.salvarLogErro) {
      const logPath = path.join(tempDir, CONFIG.debug.arquivoLogErro);
      const logContent = `\n${'═'.repeat(70)}\nERRO FFmpeg - ${new Date().toISOString()}\nGrupo: ${grupoId}\n${'═'.repeat(70)}\nComando: ${cmd}\n\nErro: ${e.message}\n${'═'.repeat(70)}\n`;
      try { fs.appendFileSync(logPath, logContent); } catch {}
    }

    throw new Error(`Merge grupo ${grupoId} falhou: ${erroMsg}`);
  }
}

function executeMergeHierarquico(videos, outputPath, batchSize, tempDir, checkpointManager, quarentenaManager) {
  let currentPaths = videos.map(v => v.path);
  let level = 0;
  const tempFiles = [];

  console.log(`\n🔄 MERGE HIERÁRQUICO`);
  console.log(`   Total: ${videos.length} vídeos | Batch: ${batchSize}`);

  try {
    while (currentPaths.length > 1 && level < CONFIG.hierarchy.maxLevels) {
      level++;

      const grupos = dividirEmGrupos(currentPaths, batchSize);
      console.log(`\n📊 Nível ${level}: ${currentPaths.length} arquivos → ${grupos.length} grupos`);

      const mergedPaths = [];

      for (let i = 0; i < grupos.length; i++) {
        const grupo = grupos[i];
        const isLastGroup = grupos.length === 1;
        const outputGrupo = isLastGroup
          ? outputPath
          : path.join(tempDir, `${CONFIG.paths.tempPrefix}L${level}_G${i}.mp4`);

        const sucesso = mergeGrupo(grupo, outputGrupo, tempDir, `L${level}G${i}`);

        if (!sucesso) {
          throw new Error(`Falha no grupo ${i} do nível ${level}`);
        }

        mergedPaths.push(outputGrupo);

        if (!isLastGroup) {
          tempFiles.push(outputGrupo);
        }
      }

      // Salva checkpoint
      if (checkpointManager) {
        checkpointManager.salvarNivel(level, mergedPaths, videos.length);
      }

      // Limpa temporários do nível anterior
      if (level > 1) {
        const prevLevelPattern = new RegExp(`${CONFIG.paths.tempPrefix}L${level - 1}_`);
        for (const tempFile of [...tempFiles]) {
          if (prevLevelPattern.test(tempFile) && fs.existsSync(tempFile)) {
            try {
              fs.unlinkSync(tempFile);
              tempFiles.splice(tempFiles.indexOf(tempFile), 1);
            } catch {}
          }
        }
      }

      currentPaths = mergedPaths;
    }

    console.log(`\n✅ Merge hierárquico concluído em ${level} níveis`);
    return currentPaths[0];

  } finally {
    // Limpa temporários restantes
    for (const tempFile of tempFiles) {
      if (fs.existsSync(tempFile) && tempFile !== outputPath) {
        try { fs.unlinkSync(tempFile); } catch {}
      }
    }
  }
}

