// SEÇÃO 6: UPSCALE E TRILHA
// ══════════════════════════════════════════════════════════════════════════════

function detectarResolucao(caminhoVideo) {
  try {
    const resultado = execSync(
      `ffprobe -v error -select_streams v:0 -show_entries stream=width,height -of csv=p=0 "${caminhoVideo}"`,
      { encoding: 'utf8', timeout: 10000 }
    ).trim();

    const [width, height] = resultado.split(',').map(Number);

    if (width && height) {
      return { width, height, detectado: true };
    }

    return { width: 0, height: 0, detectado: false };
  } catch {
    return { width: 0, height: 0, detectado: false };
  }
}

function verificarNecessidadeUpscale(caminhoVideo) {
  if (!CONFIG.upscale?.habilitado) {
    return { necessario: false, motivo: 'desabilitado' };
  }

  const resolucao = detectarResolucao(caminhoVideo);
  if (!resolucao.detectado) {
    return { necessario: false, motivo: 'não foi possível detectar resolução' };
  }

  const { largura, altura, tolerancia } = CONFIG.upscale;

  if (resolucao.width >= largura - tolerancia && resolucao.height >= altura - tolerancia) {
    if (CONFIG.upscale.apenasSeNecessario) {
      return { 
        necessario: false, 
        motivo: 'já está em 1080p',
        resolucaoAtual: resolucao
      };
    }
  }

  return {
    necessario: true,
    motivo: `${resolucao.width}x${resolucao.height} → ${largura}x${altura}`,
    resolucaoAtual: resolucao
  };
}

function aplicarUpscale(inputPath, outputPath, crf) {
  if (!CONFIG.upscale.habilitado) {
    return { aplicado: false, motivo: 'desabilitado' };
  }

  const verificacao = verificarNecessidadeUpscale(inputPath);
  if (!verificacao.necessario) {
    console.log(`\n📐 UPSCALE: ${verificacao.motivo}`);
    return { aplicado: false, motivo: verificacao.motivo };
  }

  console.log(`\n📐 UPSCALE PARA 1080p...`);
  console.log(`   ${verificacao.motivo}`);

  const { largura, altura, algoritmo } = CONFIG.upscale;

  const cmd = `ffmpeg -y -i "${inputPath}" ` +
    `-vf "scale=${largura}:${altura}:flags=${algoritmo}" ` +
    `-c:v ${CONFIG.encoding.videoCodec} ` +
    `-preset ${CONFIG.encoding.preset} ` +
    `-crf ${crf} ` +
    `-pix_fmt ${CONFIG.encoding.pixFmt} ` +
    `-c:a copy ` +
    `"${outputPath}" 2>&1`;

  try {
    execSync(cmd, { timeout: CONFIG.timeouts.upscaleMs, maxBuffer: 50 * 1024 * 1024 });

    if (fs.existsSync(outputPath) && fs.statSync(outputPath).size > 1000) {
      console.log(`   ✅ Upscale concluído!`);
      return { aplicado: true, arquivo: outputPath };
    } else {
      throw new Error('Arquivo inválido');
    }
  } catch (e) {
    console.log(`   ⚠️ Upscale falhou: ${e.message.substring(0, 100)}`);
    return { aplicado: false, erro: e.message };
  }
}

function buscarTrilha(pastaObra, nomeObra) {
  for (const template of CONFIG.trilha.buscarEm) {
    const caminho = template
      .replace('{pasta_obra}', pastaObra)
      .replace('{nome_obra}', nomeObra);

    if (fs.existsSync(caminho)) {
      console.log(`🎵 Trilha encontrada: ${caminho}`);
      return caminho;
    }
  }

  console.log(`⚠️ Nenhuma trilha encontrada`);
  return null;
}

function obterDuracaoFinal(videoPath) {
  try {
    const resultado = execSync(
      `ffprobe -v error -show_entries format=duration -of csv=p=0 "${videoPath}"`,
      { encoding: 'utf8', timeout: 10000 }
    ).trim();
    return parseFloat(resultado) || 0;
  } catch {
    return 0;
  }
}

function adicionarTrilha(videoSemTrilha, videoCompleto, trilhaPath) {
  if (!CONFIG.trilha.habilitado || !trilhaPath) {
    return { sucesso: false, motivo: 'trilha não disponível' };
  }

  console.log(`\n🎵 ADICIONANDO TRILHA...`);

  const duracaoVideo = obterDuracaoFinal(videoSemTrilha);
  if (duracaoVideo === 0) {
    return { sucesso: false, erro: 'Duração não detectada' };
  }

  const fadeOutStart = Math.max(0, duracaoVideo - CONFIG.trilha.fadeOut);

  // ⚠️ CRÍTICO: Manter -ar 24000 para consistência
  const cmd = `ffmpeg -y -i "${videoSemTrilha}" -stream_loop -1 -i "${trilhaPath}" ` +
    `-filter_complex "[0:a]volume=1.0[orig];` +
    `[1:a]afade=t=in:st=0:d=${CONFIG.trilha.fadeIn},` +
    `volume=${CONFIG.trilha.volume},` +
    `afade=t=out:st=${fadeOutStart}:d=${CONFIG.trilha.fadeOut}[music];` +
    `[orig][music]amix=inputs=2:duration=first[aout]" ` +
    `-map 0:v -map "[aout]" ` +
    `-c:v copy ` +
    `-c:a ${CONFIG.encoding.audioCodec} ` +
    `-ar ${CONFIG.encoding.audioSampleRate} ` +
    `-ac ${CONFIG.encoding.audioChannels} ` +
    `-b:a ${CONFIG.encoding.audioBitrate} ` +
    `-shortest ` +
    `"${videoCompleto}" 2>&1`;

  try {
    execSync(cmd, { timeout: CONFIG.timeouts.trilhaMs, maxBuffer: 50 * 1024 * 1024 });

    if (fs.existsSync(videoCompleto) && fs.statSync(videoCompleto).size > 1000) {
      console.log(`   ✅ Trilha adicionada!`);
      return { sucesso: true, arquivo: videoCompleto };
    } else {
      throw new Error('Arquivo inválido');
    }
  } catch (e) {
    console.log(`   ⚠️ Falha: ${e.message.substring(0, 100)}`);
    return { sucesso: false, erro: e.message };
  }
}

