// SEÇÃO 7: PROCESSAMENTO PRINCIPAL
// ══════════════════════════════════════════════════════════════════════════════

function processarObra(obra) {
  const startTime = Date.now();

  console.log(`\n╔══════════════════════════════════════════════════════════════════════╗`);
  console.log(`║                    PROCESSANDO OBRA v2.6                             ║`);
  console.log(`╠══════════════════════════════════════════════════════════════════════╣`);
  console.log(`║  Nome: ${obra.nome.padEnd(61)}║`);
  console.log(`║  Pasta: ${obra.caminho.substring(0, 59).padEnd(60)}║`);
  if (CONFIG.dryRun.ativo) {
    console.log(`║  ⚠️ MODO DRY-RUN ATIVO                                               ║`);
  }
  if (CONFIG.debug.habilitado) {
    console.log(`║  🐛 DEBUG MODE ATIVO                                                 ║`);
  }
  console.log(`╚══════════════════════════════════════════════════════════════════════╝`);

  const resultados = [];

  for (const idioma of CONFIG.idiomas.filter(i => i.ativo)) {
    const resultado = processarObraIdioma(obra, idioma);
    resultados.push(resultado);
  }

  const tempoTotal = Math.round((Date.now() - startTime) / 1000);
  console.log(`\n⏱️ Tempo total: ${tempoTotal}s`);

  return resultados;
}

function processarObraIdioma(obra, idioma) {
  const startTime = Date.now();

  // 🆕 v2.6: Inicializa report e system monitor
  const report = new ReportGenerator(obra.nome, idioma.pasta);
  const webhook = new WebhookNotifier();
  const systemMonitor = new SystemMonitor();

  report.section(`IDIOMA: ${idioma.pasta}`);

  const result = {
    sucesso: false,
    obra: obra.nome,
    idioma: idioma.pasta,
    arquivoSemTrilha: null,
    arquivoCompleto: null,
    tamanhoMB: 0,
    tempoSegundos: 0,
    totalVideos: 0,
    capitulos: null,
    erro: null
  };

  try {
    // 1. Detecta vídeos
    let videos = detectarVideos(obra.caminho, idioma);

    if (videos.length === 0) {
      result.erro = 'Nenhum vídeo encontrado';
      report.error('Nenhum vídeo encontrado');
      return result;
    }

    report.log(`Encontrados: ${videos.length} vídeos`);
    report.log(`Páginas: ${videos[0].pageNum} a ${videos[videos.length - 1].pageNum}`);

    // 🧪 MODO DE TESTE
    if (CONFIG.modoTeste.ativo) {
      const totalOriginal = videos.length;
      videos = videos.slice(0, CONFIG.modoTeste.maxVideos);
      report.warning(`MODO DE TESTE: ${videos.length} de ${totalOriginal} vídeos`);
    }

    result.totalVideos = videos.length;

    // 2. Configura diretórios
    const compiladoDir = path.join(obra.caminho, CONFIG.paths.compiladoDir);
    if (!fs.existsSync(compiladoDir)) {
      fs.mkdirSync(compiladoDir, { recursive: true });
    }

    const tempDir = path.join(obra.caminho, '.temp_merge');
    if (!fs.existsSync(tempDir)) {
      fs.mkdirSync(tempDir, { recursive: true });
    }

    // 3. Inicializa managers
    const configPath = path.join(compiladoDir, CONFIG.paths.configFile);
    const configManager = new ConfigManager(configPath);
    const checkpointManager = new CheckpointManager(compiladoDir);
    const quarentenaManager = new QuarentenaManager(obra.caminho);
    quarentenaManager.inicializar();

    // 🆕 v2.6: Estimativa de tempo
    const estimativa = configManager.estimarTempo(videos.length);
    report.log(`Tempo estimado: ~${estimativa.tempoEstimadoMinutos} min (${estimativa.confianca})`);

    // 4. Verifica checkpoint anterior
    const checkpoint = checkpointManager.verificarRecuperacao();
    if (checkpoint.temCheckpoint) {
      report.warning(`Checkpoint encontrado do nível ${checkpoint.dados.nivel}`);
      checkpointManager.limpar();
    }

    // 5. Verifica disco e calcula CRF adaptativo
    const espacoDisco = DiskMonitor.verificarEspaco(obra.caminho);
    if (espacoDisco) {
      report.log(`Disco: ${espacoDisco.livreGB}GB livres (${espacoDisco.percentUsado}% usado)`);

      const alerta = DiskMonitor.verificarAlerta(obra.caminho);
      if (alerta) {
        report.warning(alerta.mensagem);
        webhook.notificarAlerta('DISCO', alerta);
      }
    }

    const ajusteCRF = DiskMonitor.calcularAjusteCRF(obra.caminho);
    const crfFinal = Math.min(CONFIG.encoding.crfMaximo, CONFIG.encoding.crf + ajusteCRF);

    // 6. Valida gaps
    const validacaoGaps = GapDetector.validar(videos, compiladoDir);
    if (validacaoGaps.temGaps) {
      report.warning(`${validacaoGaps.gaps.length} páginas faltando`);
    }
    if (!validacaoGaps.valido) {
      result.erro = 'Gaps na sequência';
      return result;
    }

    // 7. Verifica consistência
    verificarConsistencia(videos);

    // 🆕 v2.7: Análise de amostra de arquivos
    const analiseArquivos = VideoAnalyzer.analisarAmostra(videos, 5);

    // 🆕 v2.7: Calcula parâmetros otimizados
    const parametrosCalc = configManager.calcularParametros(analiseArquivos);

    // 🆕 v2.7: Verifica consistência de áudio
    const consistenciaAudio = AudioAnalyzer.verificarConsistencia(videos);
    if (consistenciaAudio.verificado && !consistenciaAudio.consistente) {
      report.warning('Inconsistência de áudio detectada entre vídeos');
    }

    // 🆕 v2.7: Validação pré-merge completa
    const validacaoPreMerge = PreMergeValidator.validar(videos, compiladoDir);
    if (validacaoPreMerge.verificado && validacaoPreMerge.inconsistencias?.length > 0) {
      report.warning(`${validacaoPreMerge.inconsistencias.length} vídeos com inconsistências`);
    }

    // 8. Nomes dos arquivos
    const timestamp = new Date().toISOString().replace(/[:.]/g, '-').substring(0, 19);
    const nomeBase = `${obra.nome}_${idioma.pasta}`;
    const arquivoMerge720 = path.join(compiladoDir, `${nomeBase}_720p_${timestamp}.mp4`);
    const arquivoMerge1080 = path.join(compiladoDir, `${nomeBase}_1080p_${timestamp}.mp4`);
    const arquivoCompleto = path.join(compiladoDir, `${nomeBase}_completo_${timestamp}.mp4`);
    const metaPath = path.join(compiladoDir, `${nomeBase}_meta.json`);

    // 🆕 v2.6: Verifica mudanças
    const mudancas = MudancasDetector.verificarMudancas(videos, metaPath);
    if (!mudancas.mudou) {
      report.log('SEM MUDANÇAS - Compilado atualizado!', 'success');
      result.sucesso = true;
      result.modo = 'SEM_MUDANCAS';
      return result;
    }

    report.log(`Mudanças detectadas: ${mudancas.motivo}`);
    MudancasDetector.gerarRelatorioDiferencas(mudancas, compiladoDir);

    // 🔍 MODO DRY-RUN
    if (CONFIG.dryRun.ativo) {
      report.section('DRY-RUN: Simulação');
      console.log(`   Vídeos: ${videos.length}`);
      console.log(`   Batch size: ${CONFIG.hierarchy.initialBatchSize}`);
      console.log(`   CRF: ${crfFinal}`);
      console.log(`   Níveis estimados: ${Math.ceil(Math.log(videos.length) / Math.log(CONFIG.hierarchy.initialBatchSize))}`);
      console.log(`   Tempo estimado: ~${estimativa.tempoEstimadoMinutos} min`);

      result.sucesso = true;
      result.modo = 'DRY_RUN';
      return result;
    }

    // 🆕 v2.6: Inicia monitoramento
    systemMonitor.iniciar();

    // Notifica início
    webhook.notificarInicio(obra.nome, idioma.pasta, videos.length);

    // 🆕 v2.6: Atualiza dashboard
    DashboardManager.atualizarStatus(compiladoDir, 'EM_ANDAMENTO', {
      totalVideos: videos.length,
      iniciadoEm: new Date().toISOString()
    });

    // 9. Verifica se já existe e faz backup
    const arquivosExistentes = fs.readdirSync(compiladoDir).filter(f => 
      f.includes(nomeBase) && f.endsWith('.mp4') && !f.includes('_backup')
    );
    let backupInfo = null;

    for (const arqExistente of arquivosExistentes) {
      const caminhoExistente = path.join(compiladoDir, arqExistente);
      backupInfo = BackupManager.moverParaBackup(caminhoExistente, compiladoDir, nomeBase);
    }

    // 10. Obtém durações para capítulos
    let duracoes = [];
    if (CONFIG.capitulos.habilitado) {
      duracoes = obterDuracoes(videos);
    }

    // 11. Merge hierárquico com retry
    let batchSize = configManager.getOptimalBatchSize(CONFIG.hierarchy.initialBatchSize);
    let retryCount = 0;
    let mergedPath = null;
    let success = false;

    report.section('MERGE HIERÁRQUICO');

    while (retryCount < CONFIG.hierarchy.maxRetries && !success) {
      try {
        console.log(`\n🔄 TENTATIVA ${retryCount + 1}/${CONFIG.hierarchy.maxRetries} (batch: ${batchSize})`);

        mergedPath = executeMergeHierarquico(videos, arquivoMerge720, batchSize, tempDir, checkpointManager, quarentenaManager);

        if (mergedPath && fs.existsSync(mergedPath)) {
          success = true;
          const tamanhoMB = (fs.statSync(mergedPath).size / (1024 * 1024)).toFixed(2);
          report.log(`MERGE CONCLUÍDO! (${tamanhoMB} MB)`, 'success');

          // 🆕 v2.7: Salva peso observado para cache
          const pesoObservado = {
            ramPorArquivoMB: analiseArquivos.tamanhoMB * 4, // Estimativa com overhead
            calculadoEm: new Date().toISOString()
          };
          configManager.recordSuccess(batchSize, videos.length, (Date.now() - startTime) / 1000, pesoObservado);
        }
      } catch (e) {
        report.error(`FALHA: ${e.message.substring(0, 100)}`);
        configManager.recordFailure(batchSize, e.message);

        // 🆕 v2.6: Registra padrão de falha
        PadroesFalhaManager.registrar(compiladoDir, e.message, {
          batchSize,
          tentativa: retryCount + 1,
          totalVideos: videos.length
        });

        batchSize = Math.max(
          CONFIG.hierarchy.minBatchSize,
          Math.floor(batchSize * CONFIG.hierarchy.reductionFactor)
        );

        console.log(`   Reduzindo batch para: ${batchSize}`);
      }

      retryCount++;
    }

    if (!success) {
      throw new Error('Todas as tentativas falharam');
    }

    // 🆕 v2.7: Validação final do arquivo merge
    const validacaoFinalResult = FinalValidator.validar(mergedPath, videos);
    if (validacaoFinalResult.verificado && !validacaoFinalResult.valido) {
      report.warning(`Validação final: ${validacaoFinalResult.problemas.join(', ')}`);
    }

    // 12. Verifica rollback
    if (backupInfo) {
      const rollbackCheck = BackupManager.verificarRollback(mergedPath, backupInfo);
      if (rollbackCheck.deveRollback) {
        BackupManager.executarRollback(mergedPath, backupInfo);
        throw new Error('Rollback executado - arquivo muito pequeno');
      }
    }

    // 13. Upscale
    report.section('UPSCALE');
    let arquivoFinal = mergedPath;
    const upscaleResult = aplicarUpscale(mergedPath, arquivoMerge1080, crfFinal);

    if (upscaleResult.aplicado) {
      arquivoFinal = arquivoMerge1080;
      if (fs.existsSync(mergedPath) && mergedPath !== arquivoMerge1080) {
        fs.unlinkSync(mergedPath);
      }
    }

    // 🆕 v2.7: Pós-processamento - Corta vídeo na duração do áudio
    const corteResult = PostProcessor.cortarNaDuracaoAudio(arquivoFinal);
    if (corteResult.cortado) {
      report.log(`Sincronização: removidos ${corteResult.removido.toFixed(1)}s de excesso`, 'success');
    }

    result.arquivoSemTrilha = arquivoFinal;

    // 14. Trilha
    report.section('TRILHA SONORA');
    const trilhaPath = buscarTrilha(obra.caminho, obra.nome);
    if (trilhaPath) {
      const trilhaResult = adicionarTrilha(arquivoFinal, arquivoCompleto, trilhaPath);
      if (trilhaResult.sucesso) {
        result.arquivoCompleto = arquivoCompleto;
      }
    }

    if (!result.arquivoCompleto) {
      result.arquivoCompleto = result.arquivoSemTrilha;
    }

    // 15. Capítulos
    if (CONFIG.capitulos.habilitado && duracoes.length > 0) {
      report.section('CAPÍTULOS');
      const chapterManager = new ChapterManager();
      chapterManager.criarCapitulosFixos(videos, duracoes, CONFIG.capitulos.intervaloFixo);
      chapterManager.mostrarResumo();
      result.capitulos = chapterManager.salvar(compiladoDir, nomeBase);
    }

    // 16. Limpa checkpoint e temporários
    checkpointManager.limpar();
    try { fs.rmSync(tempDir, { recursive: true, force: true }); } catch {}

    // 17. Estatísticas finais
    if (fs.existsSync(result.arquivoCompleto)) {
      result.tamanhoMB = parseFloat((fs.statSync(result.arquivoCompleto).size / (1024 * 1024)).toFixed(2));
    }

    result.tempoSegundos = Math.round((Date.now() - startTime) / 1000);
    result.sucesso = true;
    result.videosQuarentena = quarentenaManager.getTotal();
    result.crfUsado = crfFinal;
    result.modo = 'COMPLETO';

    // 🆕 v2.7: Campos adicionais
    result.validacaoFinal = validacaoFinalResult;
    result.corteAudioVideo = corteResult;
    result.consistenciaAudio = consistenciaAudio;

    // 🆕 v2.6: Para monitoramento e coleta estatísticas
    systemMonitor.parar();
    const statsFinais = systemMonitor.getEstatisticas();
    result.estatisticasSistema = statsFinais;

    // 18. Salva metadados
    const videosInfo = MudancasDetector.coletarInfoVideos(videos);
    AtomicWriter.escreverJSON(metaPath, {
      criadoEm: new Date().toISOString(),
      versao: '2.8',
      paginaInicio: videos[0].pageNum,
      paginaFim: videos[videos.length - 1].pageNum,
      totalPaginas: videos.length,
      crfUsado: crfFinal,
      videosEmQuarentena: quarentenaManager.getTotal(),
      estatisticasSistema: statsFinais,
      // 🆕 v2.7: Informações adicionais
      validacaoFinal: validacaoFinalResult,
      corteAudioVideo: corteResult,
      consistenciaAudio: consistenciaAudio,
      analiseArquivos: analiseArquivos,
      cache: {
        videosUsados: videosInfo,
        hashLista: MudancasDetector.gerarHashLista(videosInfo)
      }
    });

    // 🆕 v2.6: Atualiza dashboard
    DashboardManager.salvar(compiladoDir, {
      status: 'CONCLUIDO',
      sucesso: true,
      ...result,
      finalizadoEm: new Date().toISOString()
    });

    // Notifica conclusão
    webhook.notificarConclusao(obra.nome, idioma.pasta, result);

    // 🆕 v2.6: Mostra resumo do sistema
    systemMonitor.mostrarResumo();
    systemMonitor.salvarLog(compiladoDir);

    // Salva relatório
    report.section('CONCLUÍDO');
    report.salvar(compiladoDir, result);

  } catch (e) {
    result.erro = e.message;
    report.error(e.message);

    // 🆕 v2.6: Registra falha
    const compiladoDir = path.join(obra.caminho, CONFIG.paths.compiladoDir);
    PadroesFalhaManager.registrar(compiladoDir, e.message, {
      fase: 'processamento',
      totalVideos: result.totalVideos
    });

    // 🆕 v2.6: Atualiza dashboard
    DashboardManager.salvar(compiladoDir, {
      status: 'ERRO',
      erro: e.message,
      finalizadoEm: new Date().toISOString()
    });

    webhook.notificarErro(obra.nome, idioma.pasta, e.message);
    systemMonitor.parar();
  }

  // Log final
  console.log(`\n═══════════════════════════════════════════════`);
  console.log(`RESULTADO ${idioma.pasta}: ${result.sucesso ? '✅ SUCESSO' : '❌ FALHA'}`);
  console.log(`Vídeos: ${result.totalVideos} | Tamanho: ${result.tamanhoMB} MB | Tempo: ${result.tempoSegundos}s`);
  if (result.arquivoCompleto) {
    console.log(`Arquivo: ${path.basename(result.arquivoCompleto)}`);
  }
  console.log(`═══════════════════════════════════════════════\n`);

  return result;
}

