function main() {
  console.log(`\n╔══════════════════════════════════════════════════════════════════════╗`);
  console.log(`║                    MERGE HIERÁRQUICO V2.8                            ║`);
  console.log(`║         V2.0 (sincronia garantida) + Melhorias V3.5/V3.6/Lite        ║`);
  console.log(`╠══════════════════════════════════════════════════════════════════════╣`);
  console.log(`║  🆕 v2.7: Análise de áudio e verificação de consistência             ║`);
  console.log(`║  🆕 v2.7: Validação final e corte automático vídeo↔áudio             ║`);
  console.log(`║  🆕 v2.8: Nice/ionice para prioridade baixa do FFmpeg                ║`);
  console.log(`║  🆕 v2.8: Sistema de CTAs (frases de engajamento)                    ║`);
  console.log(`║  🆕 v2.8: Trilha sonora melhorada com amix e fade                    ║`);
  console.log(`╚══════════════════════════════════════════════════════════════════════╝`);

  if (CONFIG.modoTeste.ativo) {
    console.log(`\n⚠️ MODO DE TESTE: Apenas ${CONFIG.modoTeste.maxVideos} vídeos`);
  }

  if (CONFIG.dryRun.ativo) {
    console.log(`\n⚠️ MODO DRY-RUN: Simulação apenas`);
  }

  if (CONFIG.debug.habilitado) {
    console.log(`\n🐛 DEBUG MODE: Logs detalhados ativados`);
  }

  if (CONFIG.concorrencia?.habilitado) {
    const cpus = require('os').cpus().length;
    console.log(`\n⚡ CONCORRÊNCIA: Até ${CONFIG.concorrencia.maxParalelo} grupos em paralelo (${cpus} CPUs)`);
  }

  if (CONFIG.prioridade?.usarNice || CONFIG.prioridade?.usarIonice) {
    console.log(`\n🔧 PRIORIDADE BAIXA: nice=${CONFIG.prioridade.usarNice} ionice=${CONFIG.prioridade.usarIonice}`);
  }

  if (CONFIG.cta?.habilitado) {
    console.log(`\n📢 CTAs HABILITADOS: Inserindo frases de engajamento`);
  }

  const resultados = [];

  try {
    let obras = [];

    if (CONFIG.modoManual.ativo) {
      console.log(`\n📌 MODO MANUAL: "${CONFIG.modoManual.nomeObra}"`);

      const obra = buscarPastaObra(CONFIG.modoManual.nomeObra);

      if (!obra) {
        return [{
          json: {
            sucesso: false,
            erro: `Obra "${CONFIG.modoManual.nomeObra}" não encontrada`,
            pastasVerificadas: CONFIG.pastasRaiz
          }
        }];
      }

      obras = [obra];
    } else {
      obras = descobrirObras();

      if (obras.length === 0) {
        return [{
          json: {
            sucesso: false,
            erro: 'Nenhuma obra encontrada',
            pastasVerificadas: CONFIG.pastasRaiz
          }
        }];
      }
    }

    for (const obra of obras) {
      const resultadosObra = processarObra(obra);
      resultados.push(...resultadosObra);
    }

  } catch (e) {
    resultados.push({
      sucesso: false,
      erro: e.message,
      stack: e.stack
    });
  }

  return resultados.map(r => ({ json: r }));
}

// Executa
return main();
